// 项目实战“复刻面试自习室”第 18 关：在线编程实验场与代码沙箱。
import type {AiLevel} from '../journey';

export const pjPlayground:AiLevel={id:'pj-playground',title:'在线编程实验场与代码沙箱',summary:'搭建在线编程实验场与受控代码沙箱：实现代码骨架 TODO 校验、超时与输出上限控制、隔离子进程运行以及测试用例自动判题',lessons:[
  {title:'这一关做什么：让代码题能跑、能测、能安全隔离',body:'第 12 关实现了单选、判断、填空的客观题自动判分，第 14 关接入了 AI 给简答题点评打分；但面试里最核心的“编程手写题”，既没法靠字符串精确匹配来判对错，也不能只让 AI 凭肉眼估算结果——代码能不能跑通边界用例、会不会死循环或报错，必须在隔离环境里真正执行测试用例。\n这一关为自习室加上在线编程实验场（Playground）与安全代码沙箱，做四件事：\n一、骨架 Diff 检查：提交运行前校验代码骨架（TODO），拦截原样未改或只加了注释的无效提交；\n二、受控子进程运行器：在独立临时目录里以最小环境变量拉起子进程，设置超时熔断、内存与输出字节上限，结束后清理临时文件；\n三、测试用例注入与自动判题接口：POST /api/playground/run 把隐藏测试驱动拼到用户代码后面执行，返回结构化的通过数、耗时、输出和逐条用例详情；\n四、前端实验场编辑器：加载题目骨架、编辑运行并展示用例结果，支持一键重置回初始骨架。'},
  {title:'浏览器沙箱 vs 服务端受控执行',body:'代码沙箱有两条常见路线，各自的定位完全不同：\n一、浏览器沙箱（Web Worker / WASM）：把 JS/TS 代码放进独立的 Web Worker 线程，屏蔽 fetch、WebSocket 等网络接口，页面不会卡死，超时直接调用 worker.terminate() 强杀；Python、SQLite 等也能通过 WASM 在浏览器里跑。它的优点是零服务器算力消耗、反馈极快；局限是无法直接编译运行原生 Go、Java 代码，而且运行在用户本机，测试结果可以被浏览器改写，只适合试跑预览，不能用于权威判题。\n二、服务端受控执行（OS 子进程 + 资源限制 / 容器）：适用于全语言判题，并且隐藏测试用例不会下发到前端。\n服务端执行有两条绝对红线：\n第一，绝不在后端主进程里直接 eval(code)、exec(code) 或 new Function(code)：与主服务同进程意味着用户代码能读到 os.environ 里的 AI_API_KEY、删除 SQLite 数据库文件甚至退出进程；\n第二，绝不把用户输入拼接到未净化的 Shell 命令（例如 sh -c "..."）：分号、反引号或 $() 会直接触发命令注入。正确做法是把源码写入临时文件，通过参数数组直接拉起子进程（禁用 shell 解析），并结合独立目录、ulimit/rlimit 资源上限或容器隔离来兜底。'},
  {title:'四道安全防线：超时、内存、输出上限与临时目录清理',body:'把任意用户代码交给服务器执行，必须同时守住四道防线：\n一、超时熔断：用户写了死循环（while True）时会一直占满 CPU。运行器必须设定严格超时（例如 2 秒），到点后不仅杀掉父进程，还要通过进程组或进程树强杀派生的孙进程；同时限制提交源码体积（例如最多 32 KB）。\n二、内存与 CPU 上限：在 Linux/macOS 上可通过 ulimit 或 resource.setrlimit 限制子进程虚拟内存（例如 256 MB）与 CPU 时间，生产环境再外包一层不联网、只读根文件系统的 Docker 容器（--memory、--cpus、--network=none），防止大数组分配拖垮宿主机。\n三、输出大小上限：用户如果循环打印几百兆内容，不能傻傻全放进内存，也不能在超过上限后直接停读管道——操作系统管道缓冲区只有几十 KB，停读而不排空会导致子进程写阻塞直到超时。正确做法是边读边截取前 16 KB，多余字节直接丢弃排空并标记 truncated=true。\n四、临时目录与环境隔离：每次运行创建随机临时目录，清空继承的环境变量（只保留 PATH 等白名单字段，绝不传入密钥），并在 defer / finally 里确保无论正常结束、报错还是超时都彻底删掉临时目录。',code:'# 服务端沙箱四道防线的核心配置与工具函数示例\nimport os\n\nMAX_CODE_BYTES = 32 * 1024\nTIMEOUT_SECONDS = 2.0\nMAX_OUTPUT_BYTES = 16 * 1024\nMAX_MEMORY_BYTES = 256 * 1024 * 1024\nSAFE_ENV_KEYS = ("PATH", "HOME", "LANG", "SystemRoot", "TEMP", "TMP")\n\n\ndef build_safe_env() -> dict[str, str]:\n    """只保留白名单环境变量，防止 AI_API_KEY 等敏感配置泄露给用户代码"""\n    env = {k: os.environ[k] for k in SAFE_ENV_KEYS if k in os.environ}\n    env["PYTHONUTF8"] = "1"\n    return env\n\n\ndef read_capped(stream, limit: int) -> tuple[str, bool]:\n    """读取子进程输出流：保留前 limit 字节，超出部分继续排空并标记截断"""\n    buf = bytearray()\n    truncated = False\n    while chunk := stream.read(4096):\n        if len(buf) < limit:\n            take = limit - len(buf)\n            buf.extend(chunk[:take])\n            if len(chunk) > take:\n                truncated = True\n        else:\n            truncated = True\n    text = buf.decode("utf-8", errors="replace")\n    if truncated:\n        text += "\\n...[输出已截断]"\n    return text, truncated',explain:[{at:'import os',text:'引入 os 读取允许传递的少量系统环境变量。'},{at:'MAX_CODE_BYTES = 32 * 1024',to:'SAFE_ENV_KEYS = ("PATH", "HOME", "LANG", "SystemRoot", "TEMP", "TMP")',text:'四项硬限制常量：源码最大 32 KB、单次运行超时 2 秒、标准输出/错误最多保留 16 KB、POSIX 虚拟内存上限 256 MB，以及允许继承的系统变量白名单。'},{at:'def build_safe_env() -> dict[str, str]:',to:'return env',text:'从白名单挑出必需变量并强制开启 UTF-8；DB_PATH、AI_API_KEY 等后端密钥绝不会出现在子进程环境里。'},{at:'def read_capped(stream, limit: int) -> tuple[str, bool]:',to:'truncated = False',text:'准备字节缓冲区与截断标记，流式分块读取子进程输出。'},{at:'while chunk := stream.read(4096):',to:'text = buf.decode("utf-8", errors="replace")',text:'每次读 4 KB：未达上限就拷入缓冲区，超出的部分仍继续读出并丢弃（排空管道），防止子进程因缓冲区写满而死锁挂起，最后把字节解码成字符串。'},{at:'if truncated:',to:'return text, truncated',text:'若发生截断则在末尾加上醒目提示，并返回文本与布尔标记。'}]},
  {title:'识别用户是否真的写了代码：骨架 Diff 检查',body:'做编程题时，编辑器会预填带有函数签名和 TODO 注释的代码骨架（例如 def two_sum(...): # TODO）。如果学习者原封不动点运行，或者只加了几个空行和注释，直接启动沙箱不仅浪费算力，也给不出有意义的测试反馈。\n我们可以直接借鉴真实项目里 lib/starter-diff.ts 的思路来做前置校验：\n一、把初始骨架和用户代码都按换行（兼容 \\r\\n 和 \\n）拆开，每行去掉首尾空白；\n二、过滤掉空行，以及以 //、#、--、/*、* 开头的纯注释行；\n三、把初始骨架里的非空行收进一个集合 starterLines；\n四、遍历用户代码里剩余的行，只保留“不在 starterLines 集合里”的真正改动行。如果有效改动行数为 0，接口直接返回 400（“请先补全 TODO 代码后再运行”），连子进程都不用启动。',code:'// 借鉴项目 lib/starter-diff.ts 的骨架对比逻辑\nconst isCommentLine = (line: string): boolean => {\n  const t = line.trim();\n  return t.startsWith(\'//\') || t.startsWith(\'#\') || t.startsWith(\'--\') || t.startsWith(\'/*\') || t.startsWith(\'*\');\n};\n\nexport function analyzeStarterDiff(userCode: string, starterCode: string) {\n  const starterLines = new Set(\n    starterCode.split(/\\r?\\n/).map((l) => l.trim()).filter(Boolean),\n  );\n  const effectiveLines = userCode\n    .split(/\\r?\\n/)\n    .map((l) => l.trim())\n    .filter((t) => t.length > 0 && !isCommentLine(t) && !starterLines.has(t));\n  return {\n    starterLines,\n    effectiveLines,\n    hasEdits: effectiveLines.length > 0,\n  };\n}',explain:[{at:'const isCommentLine = (line: string): boolean => {',to:'};',text:'识别各常见语言的纯注释行前缀（JS/Go/Java 的 // 与 /* *、Python 的 #、SQL 的 --），防止只写注释绕过检查。'},{at:'export function analyzeStarterDiff(userCode: string, starterCode: string) {',to:');',text:'把初始骨架拆行、去首尾空白并去空行后存进 Set，后续比对每行只需 O(1) 时间。'},{at:'const effectiveLines = userCode',to:'.filter((t) => t.length > 0 && !isCommentLine(t) && !starterLines.has(t));',text:'对用户提交的代码同样拆行并去空白，同时过滤掉空行、纯注释行以及原样来自骨架模板的行，只留下用户真正写出的实现代码。'},{at:'return {',to:'}',text:'返回骨架集合、有效改动行列表以及是否通过校验的布尔标记。'}]},
  {title:'实验场接口与编程题约定',body:'这一关新增两个接口，全部需要登录（未登录返回 401）。\n为了保证不管你在前面选择了 Go、Java、Node.js 还是 Python 后端，都能立刻在本机跑通全部验收检查，我们的沙箱运行器统一支持运行 Python 代码（第 2 关起每台电脑都已经装好了 Python 3），同时按语言路由表留好了扩展位置。\n内置题目先提供一道经典的 "two-sum"（两数之和），包含 3 组不返回给前端的隐藏测试用例；接口通过独立的结果文件与 stdout 分离收集用例结果，即使 stdout 被截断也不影响判题结构化返回。',code:'GET  /api/playground/problems\n→ 200 {"items": [{"id": "two-sum", "title": "两数之和", "language": "python", "starter": "def two_sum(nums, target):\\n    ..."}]}\n\nPOST /api/playground/run   {"problemId": "two-sum", "language": "python", "code": "..."}\n→ 200 {\n    "passed": 3, "total": 3, "timeMs": 38,\n    "stdout": "", "stderr": "",\n    "timedOut": false, "truncated": false,\n    "cases": [{"name": "示例 1", "ok": true, "actual": "[0, 1]", "expected": "[0, 1]"}]\n  }\n\n错误：400 代码为空、超长（>32KB）、暂不支持该语言、或未对骨架做有效改动\n      401 未登录  ·  404 题目不存在',explain:[{at:'GET  /api/playground/problems',to:'"starter":',text:'获取实验场题目列表与默认代码骨架，前端打开页面时调用。隐藏测试用例不会出现在返回里。'},{at:'POST /api/playground/run',to:'"cases":',text:'提交代码到沙箱执行并自动判题：只要进入沙箱执行（即使报错、超时或未通过用例），HTTP 状态码都是 200，由 passed、cases、stderr 和 timedOut 表达真实运行结果。'},{at:'错误：400',to:'404 题目不存在',text:'请求参数不合法、未改动 TODO 骨架返回 400；未登录返回 401；题目编号不存在返回 404。'}]},
  {title:'任务一：受控代码运行器（子进程隔离与超时熔断）',body:'先写只负责“安全拉起子进程并回收结果”的运行器模块。它接收源文件名、源码、可选的结果文件名以及要执行的命令，完成四件事：建独立临时目录、用精简环境变量启动子进程、超时强制结束进程并截断输出、最后清理临时目录。',variants:{go:{practice:{steps:['新建 internal/sandbox/runner.go，读懂已经给出的 readLimited 和 safeEnv，补完 TODO 1、2、3。','运行 go build ./... 确认能编译通过。'],expect:'go build ./... 没有任何报错输出'},code:'// internal/sandbox/runner.go\npackage sandbox\n\nimport (\n    "bytes"\n    "context"\n    "errors"\n    "io"\n    "os"\n    "os/exec"\n    "path/filepath"\n    "sync"\n    "time"\n)\n\nconst (\n    DefaultTimeout = 2 * time.Second\n    MaxOutputBytes = 16 * 1024\n)\n\ntype Result struct {\n    Stdout     string `json:"stdout"`\n    Stderr     string `json:"stderr"`\n    ExitCode   int    `json:"exitCode"`\n    TimedOut   bool   `json:"timedOut"`\n    Truncated  bool   `json:"truncated"`\n    TimeMs     int64  `json:"timeMs"`\n    ResultJSON string `json:"-"`\n}\n\nfunc safeEnv() []string {\n    allow := []string{"PATH", "HOME", "LANG", "SystemRoot", "TEMP", "TMP"}\n    env := []string{"PYTHONUTF8=1"}\n    for _, key := range allow {\n        if v := os.Getenv(key); v != "" {\n            env = append(env, key+"="+v)\n        }\n    }\n    return env\n}\n\n// readLimited 保留前 limit 字节并标记是否截断，同时排空剩余字节避免子进程写管道阻塞。\nfunc readLimited(r io.Reader, limit int) (string, bool) {\n    var buf bytes.Buffer\n    chunk := make([]byte, 4096)\n    truncated := false\n    for {\n        n, err := r.Read(chunk)\n        if n > 0 {\n            if buf.Len() < limit {\n                take := min(n, limit-buf.Len())\n                buf.Write(chunk[:take])\n                if take < n {\n                    truncated = true\n                }\n            } else {\n                truncated = true\n            }\n        }\n        if err != nil {\n            break\n        }\n    }\n    text := buf.String()\n    if truncated {\n        text += "\\n...[输出已截断]"\n    }\n    return text, truncated\n}\n\nfunc Run(filename, source, resultFile, cmdName string, args ...string) (Result, error) {\n    // TODO 1：os.MkdirTemp("", "zixishi-sb-*") 创建临时目录并 defer os.RemoveAll(dir)，把 source 写进 filename\n    // TODO 2：用 context.WithTimeout 创建带 DefaultTimeout 的 ctx，再用 exec.CommandContext 启动 cmdName（附带 args）；\n    //         设置 cmd.Dir = dir、cmd.Env = safeEnv()、cmd.WaitDelay = 300 * time.Millisecond\n    // TODO 3：打开 stdout/stderr 管道后 Start()，并发用 readLimited 读取，Wait() 等结束并统计 TimeMs；\n    //         若 ctx.Err() 是 context.DeadlineExceeded，标记 TimedOut=true 并追加超时提示到 Stderr；\n    //         若 resultFile 非空，在删除 dir 前尝试 os.ReadFile 读取到 ResultJSON\n    _ = sync.WaitGroup{}\n    _ = filepath.Join\n    _ = errors.New\n    return Result{}, nil\n}',explain:[{at:'// internal/sandbox/runner.go',to:'"time"',text:'新建 sandbox 包，负责隔离子进程执行。只使用 Go 标准库。'},{at:'const (',to:'MaxOutputBytes = 16 * 1024',text:'默认超时 2 秒，单个流输出保留上限 16 KB。'},{at:'type Result struct {',to:'ResultJSON string `json:"-"`',text:'运行结果结构体；ResultJSON 带 json:"-" 标记，只在服务端内部用来读取测试结果文件，不直接序列化返回前端。'},{at:'func safeEnv() []string {',to:'return env',text:'白名单过滤环境变量：只允许系统基础变量，绝不把 AI_API_KEY、数据库路径等敏感配置传给用户代码。'},{at:'func readLimited(r io.Reader, limit int) (string, bool) {',to:'return text, truncated',text:'流式读取管道：达到上限后不再往 buf 写，但循环继续读取直到 EOF（排空管道），避免子进程因为管道缓冲区满而阻塞挂死。'},{at:'func Run(filename, source, resultFile, cmdName string, args ...string) (Result, error) {',to:'return Result{}, nil',text:'核心沙箱执行函数，要你补全三处 TODO。'}],solution:{code:'// internal/sandbox/runner.go\npackage sandbox\n\nimport (\n    "bytes"\n    "context"\n    "errors"\n    "io"\n    "os"\n    "os/exec"\n    "path/filepath"\n    "sync"\n    "time"\n)\n\nconst (\n    DefaultTimeout = 2 * time.Second\n    MaxOutputBytes = 16 * 1024\n)\n\ntype Result struct {\n    Stdout     string `json:"stdout"`\n    Stderr     string `json:"stderr"`\n    ExitCode   int    `json:"exitCode"`\n    TimedOut   bool   `json:"timedOut"`\n    Truncated  bool   `json:"truncated"`\n    TimeMs     int64  `json:"timeMs"`\n    ResultJSON string `json:"-"`\n}\n\nfunc safeEnv() []string {\n    allow := []string{"PATH", "HOME", "LANG", "SystemRoot", "TEMP", "TMP"}\n    env := []string{"PYTHONUTF8=1"}\n    for _, key := range allow {\n        if v := os.Getenv(key); v != "" {\n            env = append(env, key+"="+v)\n        }\n    }\n    return env\n}\n\n// readLimited 保留前 limit 字节并标记是否截断，同时排空剩余字节避免子进程写管道阻塞。\nfunc readLimited(r io.Reader, limit int) (string, bool) {\n    var buf bytes.Buffer\n    chunk := make([]byte, 4096)\n    truncated := false\n    for {\n        n, err := r.Read(chunk)\n        if n > 0 {\n            if buf.Len() < limit {\n                take := min(n, limit-buf.Len())\n                buf.Write(chunk[:take])\n                if take < n {\n                    truncated = true\n                }\n            } else {\n                truncated = true\n            }\n        }\n        if err != nil {\n            break\n        }\n    }\n    text := buf.String()\n    if truncated {\n        text += "\\n...[输出已截断]"\n    }\n    return text, truncated\n}\n\nfunc Run(filename, source, resultFile, cmdName string, args ...string) (Result, error) {\n    dir, err := os.MkdirTemp("", "zixishi-sb-*")\n    if err != nil {\n        return Result{}, err\n    }\n    defer os.RemoveAll(dir)\n    if err := os.WriteFile(filepath.Join(dir, filename), []byte(source), 0600); err != nil {\n        return Result{}, err\n    }\n    ctx, cancel := context.WithTimeout(context.Background(), DefaultTimeout)\n    defer cancel()\n    cmd := exec.CommandContext(ctx, cmdName, args...)\n    cmd.Dir = dir\n    cmd.Env = safeEnv()\n    cmd.WaitDelay = 300 * time.Millisecond\n    stdoutPipe, err := cmd.StdoutPipe()\n    if err != nil {\n        return Result{}, err\n    }\n    stderrPipe, err := cmd.StderrPipe()\n    if err != nil {\n        return Result{}, err\n    }\n    started := time.Now()\n    if err := cmd.Start(); err != nil {\n        return Result{}, err\n    }\n    var outText, errText string\n    var outTrunc, errTrunc bool\n    var wg sync.WaitGroup\n    wg.Add(2)\n    go func() {\n        defer wg.Done()\n        outText, outTrunc = readLimited(stdoutPipe, MaxOutputBytes)\n    }()\n    go func() {\n        defer wg.Done()\n        errText, errTrunc = readLimited(stderrPipe, MaxOutputBytes)\n    }()\n    wg.Wait()\n    waitErr := cmd.Wait()\n    res := Result{\n        Stdout:    outText,\n        Stderr:    errText,\n        Truncated: outTrunc || errTrunc,\n        TimeMs:    time.Since(started).Milliseconds(),\n    }\n    if errors.Is(ctx.Err(), context.DeadlineExceeded) {\n        res.TimedOut = true\n        res.ExitCode = 124\n        if res.Stderr != "" {\n            res.Stderr += "\\n"\n        }\n        res.Stderr += "执行超时（超过 2 秒），已强制终止"\n    } else if waitErr != nil {\n        var exitErr *exec.ExitError\n        if errors.As(waitErr, &exitErr) {\n            res.ExitCode = exitErr.ExitCode()\n        } else {\n            res.ExitCode = 1\n        }\n    }\n    if resultFile != "" {\n        if raw, err := os.ReadFile(filepath.Join(dir, resultFile)); err == nil && len(raw) <= 64*1024 {\n            res.ResultJSON = string(raw)\n        }\n    }\n    return res, nil\n}',explain:[{at:'// internal/sandbox/runner.go',to:'"time"',text:'新建 sandbox 包，负责隔离子进程执行。只使用 Go 标准库。'},{at:'const (',to:'MaxOutputBytes = 16 * 1024',text:'默认超时 2 秒，单个流输出保留上限 16 KB。'},{at:'type Result struct {',to:'ResultJSON string `json:"-"`',text:'运行结果结构体；ResultJSON 只供内部读取用例结果文件，不直接序列化返回前端。'},{at:'func safeEnv() []string {',to:'return env',text:'白名单过滤环境变量，避免后端密钥泄漏。'},{at:'func readLimited(r io.Reader, limit int) (string, bool) {',to:'return text, truncated',text:'流式读取输出管道并在上限处截断，多余内容继续丢弃排空。'},{at:'func Run(',to:'ctx, cancel := context.WithTimeout(',text:'创建独立临时目录并用 defer 确保结束必清理，写入源码并设置 2 秒超时上下文。'},{at:'defer cancel()',to:'cmd.WaitDelay = 300 * time.Millisecond',text:'装配命令与精简环境变量；WaitDelay 保证即使子进程还留有孙进程占着管道，超时强杀后也不会一直卡住 Wait。Linux 生产环境还可进一步加上 SysProcAttr{Setpgid: true} 整组强杀。'},{at:'stdoutPipe, err := cmd.StdoutPipe()',to:'var outText, errText string',text:'拿到两个输出管道并启动子进程，随后声明文本与截断状态接收变量。'},{at:'var outTrunc, errTrunc bool',to:'waitErr := cmd.Wait()',text:'起两个协程并发读取 stdout 和 stderr，先 WaitGroup 等管道关闭，再调用 cmd.Wait() 回收子进程状态（这是标准库 StdoutPipe 的要求）。'},{at:'res := Result{',to:'res.Stderr += "执行超时（超过 2 秒），已强制终止"',text:'统计耗时；如果触发 DeadlineExceeded 说明超时强杀，记录 exitCode=124 和提示。'},{at:'} else if waitErr != nil {',to:'return res, nil',text:'否则从 ExitError 取退出码；并在临时目录清理之前，读出隐藏测试写好的结果文件。'}]}},java:{practice:{steps:['新建 src/main/java/com/example/zixishi/sandbox/SandboxRunner.java，补完 TODO 1、2、3。','运行 mvnw test-compile 确认编译没有报错。'],expect:'BUILD SUCCESS；下一个任务把它接进实验场接口'},code:'// sandbox/SandboxRunner.java\npackage com.example.zixishi.sandbox;\n\nimport java.io.ByteArrayOutputStream;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.util.Comparator;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.concurrent.TimeUnit;\nimport org.springframework.stereotype.Component;\n\n@Component\npublic class SandboxRunner {\n\n    public static final long TIMEOUT_MS = 2000;\n    public static final int MAX_OUTPUT_BYTES = 16 * 1024;\n    private static final List<String> SAFE_ENV = List.of("PATH", "HOME", "LANG", "SystemRoot", "TEMP", "TMP");\n\n    public record RunResult(String stdout, String stderr, int exitCode, boolean timedOut, boolean truncated,\n                            long timeMs, String resultJson) {}\n\n    private record StreamCapture(String text, boolean truncated) {}\n\n    private static StreamCapture readLimited(InputStream in, int limit) throws IOException {\n        ByteArrayOutputStream buf = new ByteArrayOutputStream();\n        byte[] chunk = new byte[4096];\n        boolean truncated = false;\n        int n;\n        while ((n = in.read(chunk)) != -1) {\n            if (buf.size() < limit) {\n                int take = Math.min(n, limit - buf.size());\n                buf.write(chunk, 0, take);\n                if (take < n) truncated = true;\n            } else {\n                truncated = true;\n            }\n        }\n        String text = buf.toString(StandardCharsets.UTF_8);\n        if (truncated) text += "\\n...[输出已截断]";\n        return new StreamCapture(text, truncated);\n    }\n\n    private static void deleteTree(Path dir) {\n        if (dir == null) return;\n        try (var walk = Files.walk(dir)) {\n            walk.sorted(Comparator.reverseOrder()).forEach(p -> {\n                try { Files.deleteIfExists(p); } catch (IOException ignored) {}\n            });\n        } catch (IOException ignored) {}\n    }\n\n    public RunResult run(String filename, String source, String resultFile, List<String> command) throws IOException, InterruptedException {\n        // TODO 1：Files.createTempDirectory("zixishi-sb-") 创建临时目录，写入 filename；用 try / finally 保证 deleteTree(dir) 必执行\n        // TODO 2：new ProcessBuilder(command).directory(dir.toFile())，清空 environment() 后只从 System.getenv 复制 SAFE_ENV 并加上 PYTHONUTF8=1\n        // TODO 3：启动进程后起两个线程分别用 readLimited 读取 getInputStream() 与 getErrorStream()；\n        //         用 process.waitFor(TIMEOUT_MS, TimeUnit.MILLISECONDS) 判断是否超时；\n        //         超时时先杀 process.descendants() 再 process.destroyForcibly()，等待读取线程结束；\n        //         在删除 dir 前尝试读取 resultFile（<= 64 KB）\n        Map<String, String> _envCheck = System.getenv();\n        long _now = System.nanoTime();\n        TimeUnit.MILLISECONDS.getClass();\n        return new RunResult("", "", 0, false, false, (_now - _now), _envCheck.getOrDefault("_", ""));\n    }\n}',explain:[{at:'// sandbox/SandboxRunner.java',to:'public class SandboxRunner {',text:'新建沙箱组件，只使用 JDK 自带类库，并用 @Component 注册给 Spring 容器。'},{at:'public static final long TIMEOUT_MS = 2000;',to:'private static final List<String> SAFE_ENV',text:'超时 2 秒、输出截断 16 KB 与安全环境变量白名单。'},{at:'public record RunResult(',to:'private record StreamCapture(String text, boolean truncated) {}',text:'运行结果记录与内部流读取结构。'},{at:'private static StreamCapture readLimited(',to:'return new StreamCapture(text, truncated);',text:'按 4 KB 分块读取子进程流，超过 16 KB 后仍继续读空管道并设置截断标记，避免子进程阻塞。'},{at:'private static void deleteTree(Path dir) {',to:'        } catch (IOException ignored) {}',text:'逆序遍历递归删除临时目录，保证先把目录里的文件删光再删目录本身。'},{at:'public RunResult run(',to:'return new RunResult(',text:'沙箱运行主方法，要你补全三处 TODO。'}],solution:{code:'// sandbox/SandboxRunner.java\npackage com.example.zixishi.sandbox;\n\nimport java.io.ByteArrayOutputStream;\nimport java.io.IOException;\nimport java.io.InputStream;\nimport java.nio.charset.StandardCharsets;\nimport java.nio.file.Files;\nimport java.nio.file.Path;\nimport java.util.Comparator;\nimport java.util.List;\nimport java.util.Map;\nimport java.util.concurrent.TimeUnit;\nimport org.springframework.stereotype.Component;\n\n@Component\npublic class SandboxRunner {\n\n    public static final long TIMEOUT_MS = 2000;\n    public static final int MAX_OUTPUT_BYTES = 16 * 1024;\n    private static final List<String> SAFE_ENV = List.of("PATH", "HOME", "LANG", "SystemRoot", "TEMP", "TMP");\n\n    public record RunResult(String stdout, String stderr, int exitCode, boolean timedOut, boolean truncated,\n                            long timeMs, String resultJson) {}\n\n    private record StreamCapture(String text, boolean truncated) {}\n\n    private static StreamCapture readLimited(InputStream in, int limit) throws IOException {\n        ByteArrayOutputStream buf = new ByteArrayOutputStream();\n        byte[] chunk = new byte[4096];\n        boolean truncated = false;\n        int n;\n        while ((n = in.read(chunk)) != -1) {\n            if (buf.size() < limit) {\n                int take = Math.min(n, limit - buf.size());\n                buf.write(chunk, 0, take);\n                if (take < n) truncated = true;\n            } else {\n                truncated = true;\n            }\n        }\n        String text = buf.toString(StandardCharsets.UTF_8);\n        if (truncated) text += "\\n...[输出已截断]";\n        return new StreamCapture(text, truncated);\n    }\n\n    private static void deleteTree(Path dir) {\n        if (dir == null) return;\n        try (var walk = Files.walk(dir)) {\n            walk.sorted(Comparator.reverseOrder()).forEach(p -> {\n                try { Files.deleteIfExists(p); } catch (IOException ignored) {}\n            });\n        } catch (IOException ignored) {}\n    }\n\n    public RunResult run(String filename, String source, String resultFile, List<String> command) throws IOException, InterruptedException {\n        Path dir = Files.createTempDirectory("zixishi-sb-");\n        try {\n            Files.writeString(dir.resolve(filename), source, StandardCharsets.UTF_8);\n            ProcessBuilder pb = new ProcessBuilder(command).directory(dir.toFile());\n            Map<String, String> env = pb.environment();\n            env.clear();\n            for (String key : SAFE_ENV) {\n                String val = System.getenv(key);\n                if (val != null && !val.isEmpty()) env.put(key, val);\n            }\n            env.put("PYTHONUTF8", "1");\n\n            long started = System.nanoTime();\n            Process process = pb.start();\n            StreamCapture[] out = new StreamCapture[1];\n            StreamCapture[] err = new StreamCapture[1];\n            Thread tOut = new Thread(() -> {\n                try { out[0] = readLimited(process.getInputStream(), MAX_OUTPUT_BYTES); } catch (IOException ignored) {}\n            });\n            Thread tErr = new Thread(() -> {\n                try { err[0] = readLimited(process.getErrorStream(), MAX_OUTPUT_BYTES); } catch (IOException ignored) {}\n            });\n            tOut.start();\n            tErr.start();\n\n            boolean finished = process.waitFor(TIMEOUT_MS, TimeUnit.MILLISECONDS);\n            boolean timedOut = !finished;\n            if (timedOut) {\n                process.descendants().forEach(ProcessHandle::destroyForcibly);\n                process.destroyForcibly();\n                process.waitFor(500, TimeUnit.MILLISECONDS);\n            }\n            tOut.join(500);\n            tErr.join(500);\n            long timeMs = (System.nanoTime() - started) / 1_000_000;\n\n            String stdout = out[0] != null ? out[0].text() : "";\n            String stderr = err[0] != null ? err[0].text() : "";\n            boolean truncated = (out[0] != null && out[0].truncated()) || (err[0] != null && err[0].truncated());\n            int exitCode = timedOut ? 124 : process.exitValue();\n            if (timedOut) {\n                stderr = (stderr.isEmpty() ? "" : stderr + "\\n") + "执行超时（超过 2 秒），已强制终止";\n            }\n            String resultJson = "";\n            if (resultFile != null && !resultFile.isEmpty()) {\n                Path rf = dir.resolve(resultFile);\n                if (Files.exists(rf) && Files.size(rf) <= 64 * 1024) {\n                    resultJson = Files.readString(rf, StandardCharsets.UTF_8);\n                }\n            }\n            return new RunResult(stdout, stderr, exitCode, timedOut, truncated, timeMs, resultJson);\n        } finally {\n            deleteTree(dir);\n        }\n    }\n}',explain:[{at:'// sandbox/SandboxRunner.java',to:'public class SandboxRunner {',text:'新建沙箱组件，只使用 JDK 自带类库，并用 @Component 注册给 Spring 容器。'},{at:'public static final long TIMEOUT_MS = 2000;',to:'private static final List<String> SAFE_ENV',text:'超时 2 秒、输出截断 16 KB 与安全环境变量白名单。'},{at:'public record RunResult(',to:'private record StreamCapture(String text, boolean truncated) {}',text:'运行结果记录与内部流读取结构。'},{at:'private static StreamCapture readLimited(',to:'return new StreamCapture(text, truncated);',text:'分块读取子进程流，达到上限后截断并排空。'},{at:'private static void deleteTree(Path dir) {',to:'        } catch (IOException ignored) {}',text:'逆序递归清理临时目录。'},{at:'public RunResult run(',to:'env.put("PYTHONUTF8", "1");',text:'创建随机临时目录并写入源码；清空环境变量后仅保留白名单变量，防止密钥泄露。'},{at:'long started = System.nanoTime();',to:'tErr.start();',text:'启动子进程并立即用两条线程并发读走 stdout 与 stderr，防止管道缓冲区填满造成死锁。'},{at:'boolean finished = process.waitFor(TIMEOUT_MS, TimeUnit.MILLISECONDS);',to:'long timeMs = (System.nanoTime() - started) / 1_000_000;',text:'等待子进程在 2 秒内结束；一旦超时，先遍历 process.descendants() 强杀所有孙进程，再销毁主进程本身。'},{at:'String stdout = out[0] != null ? out[0].text() : "";',to:'stderr = (stderr.isEmpty() ? "" : stderr + "\\n") + "执行超时（超过 2 秒），已强制终止";',text:'合并流输出与截断标记，超时时追加清晰提示与退出码 124。'},{at:'String resultJson = "";',to:'return new RunResult(stdout, stderr, exitCode, timedOut, truncated, timeMs, resultJson);',text:'清理目录前读取测试驱动写出的结果 JSON。'},{at:'} finally {',to:'deleteTree(dir);',text:'无论成功、异常还是超时，finally 块保证删除临时目录。'}]}},node:{practice:{steps:['新建 src/sandbox/runner.js，补完 TODO 1、2、3。','在终端跑一行 node -e "require(\'./src/sandbox/runner\')" 确认没有语法报错。'],expect:'命令正常退出，无语法错误'},code:'// src/sandbox/runner.js\nconst { spawn } = require("node:child_process");\nconst fs = require("node:fs");\nconst os = require("node:os");\nconst path = require("node:path");\n\nconst TIMEOUT_MS = 2000;\nconst MAX_OUTPUT_BYTES = 16 * 1024;\nconst SAFE_ENV_KEYS = ["PATH", "HOME", "LANG", "SystemRoot", "TEMP", "TMP"];\n\nfunction safeEnv() {\n  const env = { PYTHONUTF8: "1" };\n  for (const key of SAFE_ENV_KEYS) {\n    if (process.env[key]) env[key] = process.env[key];\n  }\n  return env;\n}\n\nfunction killTree(child) {\n  if (!child.pid) return;\n  try {\n    if (process.platform !== "win32") process.kill(-child.pid, "SIGKILL");\n    else child.kill("SIGKILL");\n  } catch {}\n}\n\nfunction makeCollector(limit) {\n  const chunks = [];\n  let bytes = 0;\n  let truncated = false;\n  return {\n    push(chunk) {\n      if (bytes >= limit) {\n        truncated = true;\n        return;\n      }\n      const rest = limit - bytes;\n      const slice = chunk.length > rest ? chunk.subarray(0, rest) : chunk;\n      chunks.push(slice);\n      bytes += slice.length;\n      if (chunk.length > rest) truncated = true;\n    },\n    result() {\n      let text = Buffer.concat(chunks).toString("utf8");\n      if (truncated) text += "\\n...[输出已截断]";\n      return { text, truncated };\n    },\n  };\n}\n\nasync function runInSandbox(filename, source, resultFile, command, args = []) {\n  // TODO 1：用 fs.mkdtempSync(path.join(os.tmpdir(), "zixishi-sb-")) 建临时目录并写入 filename；在 finally 里 fs.rmSync 递归清理\n  // TODO 2：用 spawn(command, args, { cwd: dir, env: safeEnv(), detached: process.platform !== "win32", stdio: ["ignore", "pipe", "pipe"], windowsHide: true }) 启动子进程；\n  //         用 makeCollector(MAX_OUTPUT_BYTES) 分别收集 stdout 和 stderr\n  // TODO 3：设置 TIMEOUT_MS 定时器，超时后标记 timedOut=true 并调用 killTree(child)；\n  //         在 "close" 事件里清理定时器，并在删目录前读取 resultFile（<= 64 KB），返回 { stdout, stderr, exitCode, timedOut, truncated, timeMs, resultJson }\n  return { stdout: "", stderr: "", exitCode: 0, timedOut: false, truncated: false, timeMs: 0, resultJson: "" };\n}\n\nmodule.exports = { runInSandbox, TIMEOUT_MS, MAX_OUTPUT_BYTES };',explain:[{at:'// src/sandbox/runner.js',to:'const path = require("node:path");',text:'引入 Node 标准库：spawn（不经过 shell 解析直接拉起进程）、fs、os 和 path。'},{at:'const TIMEOUT_MS = 2000;',to:'const SAFE_ENV_KEYS =',text:'定义超时、输出截断上限和环境变量白名单。'},{at:'function safeEnv() {',to:'return env;',text:'只把白名单环境变量传给子进程，隔绝密钥与数据库配置。'},{at:'function killTree(child) {',to:'  } catch {}',text:'跨平台杀进程工具：在 Linux/macOS 配合 detached: true 给负 PID 发 SIGKILL 整组强杀；Windows 下直接杀掉子进程。'},{at:'function makeCollector(limit) {',to:'};',text:'流式字节收集器：达到 16 KB 后不再保留新块，只记下 truncated=true 标记，最后统一拼接并在末尾加提示。'},{at:'async function runInSandbox(',to:'return { stdout: "", stderr: ""',text:'核心沙箱执行函数，要你补全三处 TODO。'},{at:'module.exports =',text:'导出运行器与限制常量。'}],solution:{code:'// src/sandbox/runner.js\nconst { spawn } = require("node:child_process");\nconst fs = require("node:fs");\nconst os = require("node:os");\nconst path = require("node:path");\n\nconst TIMEOUT_MS = 2000;\nconst MAX_OUTPUT_BYTES = 16 * 1024;\nconst SAFE_ENV_KEYS = ["PATH", "HOME", "LANG", "SystemRoot", "TEMP", "TMP"];\n\nfunction safeEnv() {\n  const env = { PYTHONUTF8: "1" };\n  for (const key of SAFE_ENV_KEYS) {\n    if (process.env[key]) env[key] = process.env[key];\n  }\n  return env;\n}\n\nfunction killTree(child) {\n  if (!child.pid) return;\n  try {\n    if (process.platform !== "win32") process.kill(-child.pid, "SIGKILL");\n    else child.kill("SIGKILL");\n  } catch {}\n}\n\nfunction makeCollector(limit) {\n  const chunks = [];\n  let bytes = 0;\n  let truncated = false;\n  return {\n    push(chunk) {\n      if (bytes >= limit) {\n        truncated = true;\n        return;\n      }\n      const rest = limit - bytes;\n      const slice = chunk.length > rest ? chunk.subarray(0, rest) : chunk;\n      chunks.push(slice);\n      bytes += slice.length;\n      if (chunk.length > rest) truncated = true;\n    },\n    result() {\n      let text = Buffer.concat(chunks).toString("utf8");\n      if (truncated) text += "\\n...[输出已截断]";\n      return { text, truncated };\n    },\n  };\n}\n\nasync function runInSandbox(filename, source, resultFile, command, args = []) {\n  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "zixishi-sb-"));\n  try {\n    fs.writeFileSync(path.join(dir, filename), source, "utf8");\n    const started = Date.now();\n    const outCol = makeCollector(MAX_OUTPUT_BYTES);\n    const errCol = makeCollector(MAX_OUTPUT_BYTES);\n    const child = spawn(command, args, {\n      cwd: dir,\n      env: safeEnv(),\n      detached: process.platform !== "win32",\n      stdio: ["ignore", "pipe", "pipe"],\n      windowsHide: true,\n    });\n    let timedOut = false;\n    const timer = setTimeout(() => {\n      timedOut = true;\n      killTree(child);\n    }, TIMEOUT_MS);\n    child.stdout.on("data", (c) => outCol.push(c));\n    child.stderr.on("data", (c) => errCol.push(c));\n\n    const code = await new Promise((resolve, reject) => {\n      child.on("error", (err) => {\n        clearTimeout(timer);\n        reject(err);\n      });\n      child.on("close", (exitCode) => {\n        clearTimeout(timer);\n        resolve(exitCode);\n      });\n    });\n\n    const out = outCol.result();\n    const err = errCol.result();\n    let stderr = err.text;\n    if (timedOut) {\n      stderr = (stderr ? stderr + "\\n" : "") + "执行超时（超过 2 秒），已强制终止";\n    }\n    let resultJson = "";\n    if (resultFile) {\n      const rf = path.join(dir, resultFile);\n      if (fs.existsSync(rf) && fs.statSync(rf).size <= 64 * 1024) {\n        resultJson = fs.readFileSync(rf, "utf8");\n      }\n    }\n    return {\n      stdout: out.text,\n      stderr,\n      exitCode: timedOut ? 124 : (code ?? 1),\n      timedOut,\n      truncated: out.truncated || err.truncated,\n      timeMs: Date.now() - started,\n      resultJson,\n    };\n  } finally {\n    fs.rmSync(dir, { recursive: true, force: true });\n  }\n}\n\nmodule.exports = { runInSandbox, TIMEOUT_MS, MAX_OUTPUT_BYTES };',explain:[{at:'// src/sandbox/runner.js',to:'const path = require("node:path");',text:'引入 Node 标准库，无需第三方依赖。'},{at:'const TIMEOUT_MS = 2000;',to:'const SAFE_ENV_KEYS =',text:'超时、输出截断上限和白名单变量。'},{at:'function safeEnv() {',to:'return env;',text:'只保留系统运行需要的最小环境变量。'},{at:'function killTree(child) {',to:'  } catch {}',text:'超时强杀整个进程组（POSIX）或子进程（Windows）。'},{at:'function makeCollector(limit) {',to:'};',text:'流式截取输出，避免大段打印撑爆内存。'},{at:'async function runInSandbox(',to:'windowsHide: true,',text:'创建临时目录并写入代码，再用 spawn（不经由 shell）拉起进程；detached 在非 Windows 下新建独立进程组，便于整组强杀。'},{at:'let timedOut = false;',to:'child.stderr.on("data", (c) => errCol.push(c));',text:'挂上超时定时器与 stdout/stderr 流监听器。'},{at:'const code = await new Promise((resolve, reject) => {',to:'resolve(exitCode);',text:'用 Promise 等待子进程彻底结束并关闭输出流（close 事件），无论成功还是出错都清除定时器。'},{at:'const out = outCol.result();',to:'resultJson = fs.readFileSync(rf, "utf8");',text:'整理输出、追加超时说明，并在清理前读取测试用例结果文件。'},{at:'return {',to:'resultJson,',text:'结构化返回结果。'},{at:'} finally {',to:'fs.rmSync(dir, { recursive: true, force: true });',text:'finally 保证临时目录必定被删除。'},{at:'module.exports =',text:'导出。'}]}},python:{practice:{steps:['新建 app/sandbox/__init__.py（空文件）和 app/sandbox/runner.py，补完 TODO 1、2、3。','运行 python -c "import app.sandbox.runner" 确认导入正常。'],expect:'命令正常退出，无导入或语法错误'},code:'# app/sandbox/runner.py\nimport os\nimport signal\nimport subprocess\nimport tempfile\nimport threading\nimport time\n\ntry:\n    import resource\nexcept ImportError:\n    resource = None\n\nTIMEOUT_SECONDS = 2.0\nMAX_OUTPUT_BYTES = 16 * 1024\nMAX_MEMORY_BYTES = 256 * 1024 * 1024\nSAFE_ENV_KEYS = ("PATH", "HOME", "LANG", "SystemRoot", "TEMP", "TMP")\n\n\ndef safe_env() -> dict[str, str]:\n    env = {k: os.environ[k] for k in SAFE_ENV_KEYS if k in os.environ}\n    env["PYTHONUTF8"] = "1"\n    return env\n\n\ndef _limit_memory():\n    if resource is None:\n        return\n    try:\n        resource.setrlimit(resource.RLIMIT_AS, (MAX_MEMORY_BYTES, MAX_MEMORY_BYTES))\n    except (ValueError, OSError):\n        pass\n\n\ndef _read_limited(stream, limit: int, box: dict, key: str):\n    buf = bytearray()\n    truncated = False\n    while chunk := stream.read(4096):\n        if len(buf) < limit:\n            take = limit - len(buf)\n            buf.extend(chunk[:take])\n            if len(chunk) > take:\n                truncated = True\n        else:\n            truncated = True\n    text = buf.decode("utf-8", errors="replace")\n    if truncated:\n        text += "\\n...[输出已截断]"\n        box["truncated"] = True\n    box[key] = text\n\n\ndef run_in_sandbox(filename: str, source: str, result_file: str, command: list[str]) -> dict:\n    # TODO 1：用 with tempfile.TemporaryDirectory(prefix="zixishi-sb-") as tmp_dir: 创建并在退出时自动清理临时目录；\n    #         把 source 写入 tmp_dir/filename\n    # TODO 2：用 subprocess.Popen 启动 command（cwd=tmp_dir, env=safe_env(), stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n    #         start_new_session=(os.name != "nt"), preexec_fn=(_limit_memory if os.name != "nt" else None)），\n    #         并用两条 threading.Thread 调用 _read_limited 并发收集 stdout 和 stderr\n    # TODO 3：proc.wait(timeout=TIMEOUT_SECONDS)；超时后用 os.killpg(proc.pid, signal.SIGKILL)（Windows 下 proc.kill()）强杀，\n    #         等待线程汇合，并在退出 with 块前读取 result_file（<= 64 KB），返回结果字典\n    _ = (signal, tempfile, threading, time)\n    return {"stdout": "", "stderr": "", "exitCode": 0, "timedOut": False, "truncated": False, "timeMs": 0, "resultJson": ""}',explain:[{at:'# app/sandbox/runner.py',to:'resource = None',text:'导入标准库；resource 在 Linux/macOS 上用于限制子进程内存，Windows 上没有该模块所以兼容处理。'},{at:'TIMEOUT_SECONDS = 2.0',to:'SAFE_ENV_KEYS =',text:'超时 2 秒、输出截断 16 KB、内存限制 256 MB 与白名单环境变量。'},{at:'def safe_env() -> dict[str, str]:',to:'return env',text:'白名单过滤环境变量，避免后端密钥泄漏给用户代码。'},{at:'def _limit_memory():',to:'pass',text:'在子进程启动前设置地址空间上限（RLIMIT_AS），防止大内存分配拖垮服务器。'},{at:'def _read_limited(stream, limit: int, box: dict, key: str):',to:'box[key] = text',text:'流式读取并截断在 16 KB，多余输出继续读出排空，避免子进程阻塞管道。'},{at:'def run_in_sandbox(',to:'return {"stdout":',text:'沙箱运行入口，要你补全三处 TODO。'}],solution:{code:'# app/sandbox/runner.py\nimport os\nimport signal\nimport subprocess\nimport tempfile\nimport threading\nimport time\n\ntry:\n    import resource\nexcept ImportError:\n    resource = None\n\nTIMEOUT_SECONDS = 2.0\nMAX_OUTPUT_BYTES = 16 * 1024\nMAX_MEMORY_BYTES = 256 * 1024 * 1024\nSAFE_ENV_KEYS = ("PATH", "HOME", "LANG", "SystemRoot", "TEMP", "TMP")\n\n\ndef safe_env() -> dict[str, str]:\n    env = {k: os.environ[k] for k in SAFE_ENV_KEYS if k in os.environ}\n    env["PYTHONUTF8"] = "1"\n    return env\n\n\ndef _limit_memory():\n    if resource is None:\n        return\n    try:\n        resource.setrlimit(resource.RLIMIT_AS, (MAX_MEMORY_BYTES, MAX_MEMORY_BYTES))\n    except (ValueError, OSError):\n        pass\n\n\ndef _read_limited(stream, limit: int, box: dict, key: str):\n    buf = bytearray()\n    truncated = False\n    while chunk := stream.read(4096):\n        if len(buf) < limit:\n            take = limit - len(buf)\n            buf.extend(chunk[:take])\n            if len(chunk) > take:\n                truncated = True\n        else:\n            truncated = True\n    text = buf.decode("utf-8", errors="replace")\n    if truncated:\n        text += "\\n...[输出已截断]"\n        box["truncated"] = True\n    box[key] = text\n\n\ndef run_in_sandbox(filename: str, source: str, result_file: str, command: list[str]) -> dict:\n    with tempfile.TemporaryDirectory(prefix="zixishi-sb-") as tmp_dir:\n        with open(os.path.join(tmp_dir, filename), "w", encoding="utf-8") as f:\n            f.write(source)\n        started = time.monotonic()\n        proc = subprocess.Popen(\n            command,\n            cwd=tmp_dir,\n            env=safe_env(),\n            stdout=subprocess.PIPE,\n            stderr=subprocess.PIPE,\n            start_new_session=(os.name != "nt"),\n            preexec_fn=(_limit_memory if os.name != "nt" else None),\n        )\n        box = {"stdout": "", "stderr": "", "truncated": False}\n        t_out = threading.Thread(target=_read_limited, args=(proc.stdout, MAX_OUTPUT_BYTES, box, "stdout"))\n        t_err = threading.Thread(target=_read_limited, args=(proc.stderr, MAX_OUTPUT_BYTES, box, "stderr"))\n        t_out.start()\n        t_err.start()\n        timed_out = False\n        try:\n            exit_code = proc.wait(timeout=TIMEOUT_SECONDS)\n        except subprocess.TimeoutExpired:\n            timed_out = True\n            exit_code = 124\n            if os.name != "nt":\n                os.killpg(proc.pid, signal.SIGKILL)\n            else:\n                proc.kill()\n            proc.wait()\n        t_out.join(timeout=1)\n        t_err.join(timeout=1)\n        time_ms = int((time.monotonic() - started) * 1000)\n        stderr = box["stderr"]\n        if timed_out:\n            stderr = (stderr + "\\n" if stderr else "") + "执行超时（超过 2 秒），已强制终止"\n        result_json = ""\n        if result_file:\n            rf = os.path.join(tmp_dir, result_file)\n            if os.path.isfile(rf) and os.path.getsize(rf) <= 64 * 1024:\n                with open(rf, "r", encoding="utf-8") as f:\n                    result_json = f.read()\n        return {\n            "stdout": box["stdout"],\n            "stderr": stderr,\n            "exitCode": exit_code,\n            "timedOut": timed_out,\n            "truncated": box["truncated"],\n            "timeMs": time_ms,\n            "resultJson": result_json,\n        }',explain:[{at:'# app/sandbox/runner.py',to:'resource = None',text:'导入标准库并兼容 Windows 下无 resource 模块的情况。'},{at:'TIMEOUT_SECONDS = 2.0',to:'SAFE_ENV_KEYS =',text:'超时、输出截断、内存限制与安全环境变量白名单。'},{at:'def safe_env() -> dict[str, str]:',to:'return env',text:'只保留系统必需环境变量，隔绝敏感配置。'},{at:'def _limit_memory():',to:'pass',text:'在 POSIX 子进程里通过 setrlimit 限制虚拟内存上限。'},{at:'def _read_limited(',to:'box[key] = text',text:'流式截断 stdout/stderr，多余数据持续排空防止管道死锁。'},{at:'def run_in_sandbox(',to:'f.write(source)',text:'TemporaryDirectory 在 with 块退出时自动清理；将用户源码写入隔离目录。'},{at:'started = time.monotonic()',to:'t_err.start()',text:'Popen 启动独立进程组（POSIX）与内存限制，并启动两条后台线程并发读空管道。'},{at:'timed_out = False',to:'t_err.join(timeout=1)',text:'等待限时结束；超时后用 os.killpg 整组强杀（Windows 用 proc.kill），再等输出线程安全退出。'},{at:'time_ms = int((time.monotonic() - started) * 1000)',to:'result_json = f.read()',text:'计算毫秒耗时、拼接超时提示，并在临时目录自动销毁前读出测试驱动生成的 JSON。'},{at:'return {',to:'"resultJson": result_json,',text:'返回完整运行结果。'}]}}}},
  {title:'任务二：注入测试用例并结构化返回执行结果',body:'这一步把任务一的运行器接进业务逻辑与接口：校验题目和语言、用骨架 Diff 检查拦截“原样白交或只写注释”、把隐藏测试驱动拼到用户代码末尾放进沙箱运行，再读取 _cases.json 整理出 { passed, total, timeMs, stdout, stderr, timedOut, truncated, cases } 返回前端。',variants:{go:{practice:{steps:['新建 internal/service/playground.go，补完 TODO 1、2、3。','新建 internal/handler/playground.go；在 handler.go 加字段与两条路由；在 main.go 初始化 PlaygroundService 并传入 handler.New。','运行 go vet ./... 和 go build ./... 确认能编译。'],expect:'go vet ./... 和 go build ./... 都没有报错'},code:'// internal/service/playground.go\npackage service\n\nimport (\n    "encoding/json"\n    "errors"\n    "os"\n    "os/exec"\n    "strings"\n\n    "zixishi/internal/sandbox"\n)\n\nvar (\n    ErrBadCode         = errors.New("代码不能为空，且不能超过 32 KB")\n    ErrNoEffectiveEdit = errors.New("请先补全 TODO 代码后再运行")\n    ErrUnsupportedLang = errors.New("暂不支持该编程语言")\n    ErrProblemNotFound = errors.New("题目不存在")\n)\n\ntype Problem struct {\n    ID       string `json:"id"`\n    Title    string `json:"title"`\n    Language string `json:"language"`\n    Starter  string `json:"starter"`\n}\n\ntype CaseResult struct {\n    Name     string `json:"name"`\n    OK       bool   `json:"ok"`\n    Actual   string `json:"actual"`\n    Expected string `json:"expected"`\n}\n\ntype RunResponse struct {\n    Passed    int          `json:"passed"`\n    Total     int          `json:"total"`\n    TimeMs    int64        `json:"timeMs"`\n    Stdout    string       `json:"stdout"`\n    Stderr    string       `json:"stderr"`\n    TimedOut  bool         `json:"timedOut"`\n    Truncated bool         `json:"truncated"`\n    Cases     []CaseResult `json:"cases"`\n}\n\nvar twoSumProblem = Problem{\n    ID:       "two-sum",\n    Title:    "两数之和",\n    Language: "python",\n    Starter: "def two_sum(nums: list[int], target: int) -> list[int]:\\n" +\n        "    # TODO：返回和为 target 的两个元素下标 [i, j]\\n" +\n        "    pass\\n",\n}\n\nconst twoSumHarness = `\nimport json, sys, traceback\n_cases = [\n    ("示例 1", [2, 7, 11, 15], 9, [0, 1]),\n    ("示例 2", [3, 2, 4], 6, [1, 2]),\n    ("重复元素", [3, 3], 6, [0, 1]),\n]\n_results = []\nfor _name, _nums, _target, _expected in _cases:\n    try:\n        _actual = two_sum(list(_nums), _target)\n        _ok = (_actual == _expected)\n        _results.append({"name": _name, "ok": _ok, "actual": json.dumps(_actual, ensure_ascii=False), "expected": json.dumps(_expected)})\n    except Exception as _e:\n        traceback.print_exc(file=sys.stderr)\n        _results.append({"name": _name, "ok": False, "actual": f"{type(_e).__name__}: {_e}", "expected": json.dumps(_expected)})\nwith open("_cases.json", "w", encoding="utf-8") as _f:\n    json.dump(_results, _f, ensure_ascii=False)\n`\n\ntype PlaygroundService struct{}\n\nfunc NewPlaygroundService() *PlaygroundService { return &PlaygroundService{} }\n\nfunc (s *PlaygroundService) Problems() []Problem { return []Problem{twoSumProblem} }\n\nfunc isCommentLine(line string) bool {\n    t := strings.TrimSpace(line)\n    return strings.HasPrefix(t, "//") || strings.HasPrefix(t, "#") || strings.HasPrefix(t, "--") || strings.HasPrefix(t, "/*") || strings.HasPrefix(t, "*")\n}\n\nfunc countEffectiveEdits(userCode, starterCode string) int {\n    // TODO 1：把 starterCode 按行拆分并去首尾空白存入 map[string]bool，\n    //         遍历 userCode 每一行，跳过空行、isCommentLine 行和 starter 已有行，统计有效改动行数\n    return 0\n}\n\nfunc findPython() string {\n    if p := os.Getenv("PYTHON_BIN"); p != "" {\n        return p\n    }\n    if p, err := exec.LookPath("python3"); err == nil {\n        return p\n    }\n    return "python"\n}\n\nfunc (s *PlaygroundService) Run(problemID, language, code string) (RunResponse, error) {\n    // TODO 2：校验 problemID 是否等于 "two-sum"（否则 ErrProblemNotFound）、language == "python"（否则 ErrUnsupportedLang）、\n    //         code 去空白后非空且字节数 <= 32*1024（否则 ErrBadCode）、countEffectiveEdits(code, twoSumProblem.Starter) > 0（否则 ErrNoEffectiveEdit）\n    // TODO 3：把 code + "\\n" + twoSumHarness 传入 sandbox.Run("main.py", ..., "_cases.json", findPython(), "main.py")；\n    //         解析 res.ResultJSON 为 []CaseResult，统计 passed 数量并返回 RunResponse（total 固定为 3）\n    _ = json.Unmarshal\n    return RunResponse{}, nil\n}\n\n// internal/handler/playground.go\npackage handler\n\nimport (\n    "encoding/json"\n    "errors"\n    "net/http"\n\n    "zixishi/internal/service"\n)\n\nfunc (h *Handler) playgroundProblems(w http.ResponseWriter, r *http.Request) {\n    if _, ok := h.requireUser(w, r); !ok {\n        return\n    }\n    writeJSON(w, http.StatusOK, map[string]any{"items": h.playground.Problems()})\n}\n\nfunc (h *Handler) playgroundRun(w http.ResponseWriter, r *http.Request) {\n    if _, ok := h.requireUser(w, r); !ok {\n        return\n    }\n    var body struct {\n        ProblemID string `json:"problemId"`\n        Language  string `json:"language"`\n        Code      string `json:"code"`\n    }\n    if err := json.NewDecoder(r.Body).Decode(&body); err != nil {\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求正文格式不对"})\n        return\n    }\n    res, err := h.playground.Run(body.ProblemID, body.Language, body.Code)\n    switch {\n    case err == nil:\n        writeJSON(w, http.StatusOK, res)\n    case errors.Is(err, service.ErrProblemNotFound):\n        writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})\n    case errors.Is(err, service.ErrBadCode), errors.Is(err, service.ErrNoEffectiveEdit), errors.Is(err, service.ErrUnsupportedLang):\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})\n    default:\n        h.serverError(w, err)\n    }\n}\n\n// 组装：Handler 加上字段 playground *service.PlaygroundService，New 多收一个参数；Routes 里加上：\n//     mux.HandleFunc("GET /api/playground/problems", h.playgroundProblems)\n//     mux.HandleFunc("POST /api/playground/run", h.playgroundRun)\n// main.go 里创建 pg := service.NewPlaygroundService() 后传给 handler.New',explain:[{at:'// internal/service/playground.go',to:'"zixishi/internal/sandbox"',text:'实验场业务逻辑层：管理题目、骨架 Diff 校验、用例注入与结果整理。'},{at:'var (',to:'ErrProblemNotFound =',text:'四种业务错误，分别对应 400 和 404。'},{at:'type Problem struct {',to:'Cases     []CaseResult `json:"cases"`',text:'题目、单个用例结果以及运行接口响应结构体。'},{at:'var twoSumProblem = Problem{',to:'pass\\n",',text:'内置的两数之和题目与初始骨架；你可以按同一格式把更多题目放进映射表。'},{at:'const twoSumHarness = `',to:'json.dump(_results, _f, ensure_ascii=False)',text:'隐藏测试驱动：调用用户写的 two_sum，把 3 组用例的执行情况写入 _cases.json，出错时也把调用栈打印到 stderr。'},{at:'`',to:'func (s *PlaygroundService) Problems()',text:'服务初始化与题目列表方法。'},{at:'func isCommentLine(line string) bool {',to:'return strings.HasPrefix',text:'识别常见单行/块注释前缀。'},{at:'func countEffectiveEdits(userCode, starterCode string) int {',to:'return 0',text:'骨架有效改动行统计，要你补全 TODO 1。'},{at:'func findPython() string {',to:'return "python"',text:'跨平台查找 Python 解释器（Windows 常用 python，Mac/Linux 常用 python3）。'},{at:'func (s *PlaygroundService) Run(',to:'return RunResponse{}, nil',text:'校验并送进沙箱跑用例，要你补全 TODO 2、3。'},{at:'// internal/handler/playground.go',to:'h.serverError(w, err)',text:'实验场两个 HTTP 接口，均要求登录；参数或骨架校验不通过返回 400，题目不存在返回 404。'}],solution:{code:'// internal/service/playground.go\npackage service\n\nimport (\n    "encoding/json"\n    "errors"\n    "os"\n    "os/exec"\n    "strings"\n\n    "zixishi/internal/sandbox"\n)\n\nvar (\n    ErrBadCode         = errors.New("代码不能为空，且不能超过 32 KB")\n    ErrNoEffectiveEdit = errors.New("请先补全 TODO 代码后再运行")\n    ErrUnsupportedLang = errors.New("暂不支持该编程语言")\n    ErrProblemNotFound = errors.New("题目不存在")\n)\n\ntype Problem struct {\n    ID       string `json:"id"`\n    Title    string `json:"title"`\n    Language string `json:"language"`\n    Starter  string `json:"starter"`\n}\n\ntype CaseResult struct {\n    Name     string `json:"name"`\n    OK       bool   `json:"ok"`\n    Actual   string `json:"actual"`\n    Expected string `json:"expected"`\n}\n\ntype RunResponse struct {\n    Passed    int          `json:"passed"`\n    Total     int          `json:"total"`\n    TimeMs    int64        `json:"timeMs"`\n    Stdout    string       `json:"stdout"`\n    Stderr    string       `json:"stderr"`\n    TimedOut  bool         `json:"timedOut"`\n    Truncated bool         `json:"truncated"`\n    Cases     []CaseResult `json:"cases"`\n}\n\nvar twoSumProblem = Problem{\n    ID:       "two-sum",\n    Title:    "两数之和",\n    Language: "python",\n    Starter: "def two_sum(nums: list[int], target: int) -> list[int]:\\n" +\n        "    # TODO：返回和为 target 的两个元素下标 [i, j]\\n" +\n        "    pass\\n",\n}\n\nconst twoSumHarness = `\nimport json, sys, traceback\n_cases = [\n    ("示例 1", [2, 7, 11, 15], 9, [0, 1]),\n    ("示例 2", [3, 2, 4], 6, [1, 2]),\n    ("重复元素", [3, 3], 6, [0, 1]),\n]\n_results = []\nfor _name, _nums, _target, _expected in _cases:\n    try:\n        _actual = two_sum(list(_nums), _target)\n        _ok = (_actual == _expected)\n        _results.append({"name": _name, "ok": _ok, "actual": json.dumps(_actual, ensure_ascii=False), "expected": json.dumps(_expected)})\n    except Exception as _e:\n        traceback.print_exc(file=sys.stderr)\n        _results.append({"name": _name, "ok": False, "actual": f"{type(_e).__name__}: {_e}", "expected": json.dumps(_expected)})\nwith open("_cases.json", "w", encoding="utf-8") as _f:\n    json.dump(_results, _f, ensure_ascii=False)\n`\n\ntype PlaygroundService struct{}\n\nfunc NewPlaygroundService() *PlaygroundService { return &PlaygroundService{} }\n\nfunc (s *PlaygroundService) Problems() []Problem { return []Problem{twoSumProblem} }\n\nfunc isCommentLine(line string) bool {\n    t := strings.TrimSpace(line)\n    return strings.HasPrefix(t, "//") || strings.HasPrefix(t, "#") || strings.HasPrefix(t, "--") || strings.HasPrefix(t, "/*") || strings.HasPrefix(t, "*")\n}\n\nfunc countEffectiveEdits(userCode, starterCode string) int {\n    starter := map[string]bool{}\n    for _, line := range strings.Split(strings.ReplaceAll(starterCode, "\\r\\n", "\\n"), "\\n") {\n        if t := strings.TrimSpace(line); t != "" {\n            starter[t] = true\n        }\n    }\n    edits := 0\n    for _, line := range strings.Split(strings.ReplaceAll(userCode, "\\r\\n", "\\n"), "\\n") {\n        t := strings.TrimSpace(line)\n        if t == "" || isCommentLine(t) || starter[t] {\n            continue\n        }\n        edits++\n    }\n    return edits\n}\n\nfunc findPython() string {\n    if p := os.Getenv("PYTHON_BIN"); p != "" {\n        return p\n    }\n    if p, err := exec.LookPath("python3"); err == nil {\n        return p\n    }\n    return "python"\n}\n\nfunc (s *PlaygroundService) Run(problemID, language, code string) (RunResponse, error) {\n    if problemID != twoSumProblem.ID {\n        return RunResponse{}, ErrProblemNotFound\n    }\n    if language != "python" {\n        return RunResponse{}, ErrUnsupportedLang\n    }\n    if strings.TrimSpace(code) == "" || len(code) > 32*1024 {\n        return RunResponse{}, ErrBadCode\n    }\n    if countEffectiveEdits(code, twoSumProblem.Starter) == 0 {\n        return RunResponse{}, ErrNoEffectiveEdit\n    }\n    res, err := sandbox.Run("main.py", code+"\\n"+twoSumHarness, "_cases.json", findPython(), "main.py")\n    if err != nil {\n        return RunResponse{}, err\n    }\n    cases := []CaseResult{}\n    if res.ResultJSON != "" {\n        _ = json.Unmarshal([]byte(res.ResultJSON), &cases)\n    }\n    passed := 0\n    for _, c := range cases {\n        if c.OK {\n            passed++\n        }\n    }\n    return RunResponse{\n        Passed:    passed,\n        Total:     3,\n        TimeMs:    res.TimeMs,\n        Stdout:    res.Stdout,\n        Stderr:    res.Stderr,\n        TimedOut:  res.TimedOut,\n        Truncated: res.Truncated,\n        Cases:     cases,\n    }, nil\n}\n\n// internal/handler/playground.go\npackage handler\n\nimport (\n    "encoding/json"\n    "errors"\n    "net/http"\n\n    "zixishi/internal/service"\n)\n\nfunc (h *Handler) playgroundProblems(w http.ResponseWriter, r *http.Request) {\n    if _, ok := h.requireUser(w, r); !ok {\n        return\n    }\n    writeJSON(w, http.StatusOK, map[string]any{"items": h.playground.Problems()})\n}\n\nfunc (h *Handler) playgroundRun(w http.ResponseWriter, r *http.Request) {\n    if _, ok := h.requireUser(w, r); !ok {\n        return\n    }\n    var body struct {\n        ProblemID string `json:"problemId"`\n        Language  string `json:"language"`\n        Code      string `json:"code"`\n    }\n    if err := json.NewDecoder(r.Body).Decode(&body); err != nil {\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": "请求正文格式不对"})\n        return\n    }\n    res, err := h.playground.Run(body.ProblemID, body.Language, body.Code)\n    switch {\n    case err == nil:\n        writeJSON(w, http.StatusOK, res)\n    case errors.Is(err, service.ErrProblemNotFound):\n        writeJSON(w, http.StatusNotFound, map[string]string{"error": err.Error()})\n    case errors.Is(err, service.ErrBadCode), errors.Is(err, service.ErrNoEffectiveEdit), errors.Is(err, service.ErrUnsupportedLang):\n        writeJSON(w, http.StatusBadRequest, map[string]string{"error": err.Error()})\n    default:\n        h.serverError(w, err)\n    }\n}\n\n// 组装：Handler 加上字段 playground *service.PlaygroundService，New 多收一个参数；Routes 里加上：\n//     mux.HandleFunc("GET /api/playground/problems", h.playgroundProblems)\n//     mux.HandleFunc("POST /api/playground/run", h.playgroundRun)\n// main.go 里创建 pg := service.NewPlaygroundService() 后传给 handler.New',explain:[{at:'// internal/service/playground.go',to:'"zixishi/internal/sandbox"',text:'实验场业务逻辑层：管理题目、骨架 Diff 校验、用例注入与结果整理。'},{at:'var (',to:'ErrProblemNotFound =',text:'四种业务错误，分别对应 400 和 404。'},{at:'type Problem struct {',to:'Cases     []CaseResult `json:"cases"`',text:'题目、单个用例结果以及运行接口响应结构体。'},{at:'var twoSumProblem = Problem{',to:'pass\\n",',text:'内置的两数之和题目与初始骨架。'},{at:'const twoSumHarness = `',to:'json.dump(_results, _f, ensure_ascii=False)',text:'隐藏测试驱动：调用用户写的 two_sum 并写入 _cases.json。'},{at:'`',to:'func (s *PlaygroundService) Problems()',text:'服务初始化与题目列表方法。'},{at:'func isCommentLine(line string) bool {',to:'return strings.HasPrefix',text:'识别单行/块注释前缀。'},{at:'func countEffectiveEdits(userCode, starterCode string) int {',to:'return edits',text:'把骨架行放入 map 集合，再遍历用户代码，跳过空行、注释和骨架已有行，计算有效修改行数。'},{at:'func findPython() string {',to:'return "python"',text:'跨平台查找 Python 解释器。'},{at:'func (s *PlaygroundService) Run(',to:'return RunResponse{}, ErrNoEffectiveEdit',text:'依次校验题目存在性、语言支持、源码大小与骨架有效改动，任一不通过即拦截，避免启动沙箱。'},{at:'res, err := sandbox.Run(',to:'    }, nil',text:'拼接测试驱动后交给沙箱执行，再解析 _cases.json 统计 passed 并组装返回。'},{at:'// internal/handler/playground.go',to:'h.serverError(w, err)',text:'实验场接口：鉴权后调用服务，错误按约定映射状态码。'}]}},java:{practice:{steps:['新建 service/PlaygroundService.java 和 controller/PlaygroundController.java，补完 TODO 1、2、3。','运行 mvnw test 确认编译和测试都通过。'],expect:'BUILD SUCCESS；下一个任务写实验场前端页面'},code:'// service/PlaygroundService.java\npackage com.example.zixishi.service;\n\nimport com.example.zixishi.sandbox.SandboxRunner;\nimport java.io.IOException;\nimport java.nio.charset.StandardCharsets;\nimport java.util.Arrays;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Set;\nimport org.springframework.stereotype.Service;\nimport tools.jackson.core.type.TypeReference;\nimport tools.jackson.databind.ObjectMapper;\n\n@Service\npublic class PlaygroundService {\n\n    public record Problem(String id, String title, String language, String starter) {}\n\n    public record CaseResult(String name, boolean ok, String actual, String expected) {}\n\n    public record RunResponse(int passed, int total, long timeMs, String stdout, String stderr,\n                              boolean timedOut, boolean truncated, List<CaseResult> cases) {}\n\n    private static final Problem TWO_SUM = new Problem(\n        "two-sum",\n        "两数之和",\n        "python",\n        "def two_sum(nums: list[int], target: int) -> list[int]:\\n"\n            + "    # TODO：返回和为 target 的两个元素下标 [i, j]\\n"\n            + "    pass\\n"\n    );\n\n    private static final String TWO_SUM_HARNESS = """\n        import json, sys, traceback\n        _cases = [\n            ("示例 1", [2, 7, 11, 15], 9, [0, 1]),\n            ("示例 2", [3, 2, 4], 6, [1, 2]),\n            ("重复元素", [3, 3], 6, [0, 1]),\n        ]\n        _results = []\n        for _name, _nums, _target, _expected in _cases:\n            try:\n                _actual = two_sum(list(_nums), _target)\n                _results.append({"name": _name, "ok": _actual == _expected, "actual": json.dumps(_actual, ensure_ascii=False), "expected": json.dumps(_expected)})\n            except Exception as _e:\n                traceback.print_exc(file=sys.stderr)\n                _results.append({"name": _name, "ok": False, "actual": f"{type(_e).__name__}: {_e}", "expected": json.dumps(_expected)})\n        with open("_cases.json", "w", encoding="utf-8") as _f:\n            json.dump(_results, _f, ensure_ascii=False)\n        """;\n\n    private final SandboxRunner runner;\n    private final ObjectMapper json;\n\n    public PlaygroundService(SandboxRunner runner, ObjectMapper json) {\n        this.runner = runner;\n        this.json = json;\n    }\n\n    public List<Problem> problems() {\n        return List.of(TWO_SUM);\n    }\n\n    private static boolean isCommentLine(String t) {\n        return t.startsWith("//") || t.startsWith("#") || t.startsWith("--") || t.startsWith("/*") || t.startsWith("*");\n    }\n\n    static int countEffectiveEdits(String userCode, String starterCode) {\n        // TODO 1：把 starterCode 按 \\r?\\n 拆行并 strip() 存入 Set<String>，\n        //         再统计 userCode 中非空、非 isCommentLine、且不在 starter 集合里的有效改动行数\n        Set<String> _s = new HashSet<>();\n        Arrays.asList(starterCode.split("\\\\r?\\\\n"));\n        return _s.size();\n    }\n\n    private static String pythonBin() {\n        String env = System.getenv("PYTHON_BIN");\n        if (env != null && !env.isBlank()) return env;\n        return System.getProperty("os.name").toLowerCase().contains("win") ? "python" : "python3";\n    }\n\n    public RunResponse run(String problemId, String language, String code) {\n        // TODO 2：校验 problemId 等于 "two-sum"（否则 404）、language 等于 "python"（否则 400）、\n        //         code 非空且 UTF-8 字节数 <= 32 * 1024（否则 400）、countEffectiveEdits > 0（否则 400）\n        // TODO 3：调用 runner.run("main.py", code + "\\n" + TWO_SUM_HARNESS, "_cases.json", List.of(pythonBin(), "main.py"))；\n        //         解析 resultJson 为 List<CaseResult>，计算 passed 并返回 RunResponse（total 为 3）\n        throw new StudyService.StudyException(500, "尚未实现");\n    }\n}\n\n// controller/PlaygroundController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.service.AuthService;\nimport com.example.zixishi.service.PlaygroundService;\nimport java.util.Map;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping("/api/playground")\npublic class PlaygroundController {\n\n    public record RunBody(String problemId, String language, String code) {}\n\n    private final AuthService auth;\n    private final PlaygroundService playground;\n\n    public PlaygroundController(AuthService auth, PlaygroundService playground) {\n        this.auth = auth;\n        this.playground = playground;\n    }\n\n    @GetMapping("/problems")\n    public Map<String, Object> problems(@CookieValue(name = "session", required = false) String token) {\n        auth.currentUser(token);\n        return Map.of("items", playground.problems());\n    }\n\n    @PostMapping("/run")\n    public PlaygroundService.RunResponse run(@CookieValue(name = "session", required = false) String token,\n                                             @RequestBody RunBody body) {\n        auth.currentUser(token);\n        return playground.run(body.problemId(), body.language(), body.code());\n    }\n}',explain:[{at:'// service/PlaygroundService.java',to:'import tools.jackson.databind.ObjectMapper;',text:'实验场业务逻辑层：注入 SandboxRunner 和 Jackson 3 ObjectMapper。'},{at:'@Service',to:'boolean timedOut, boolean truncated, List<CaseResult> cases) {}',text:'声明题目、单个用例结果与判题响应的数据结构。'},{at:'private static final Problem TWO_SUM',to:'""";',text:'内置“两数之和”题面骨架以及隐藏测试驱动（把结果写入 _cases.json）。'},{at:'private final SandboxRunner runner;',to:'return List.of(TWO_SUM);',text:'构造函数注入与题目列表方法。'},{at:'private static boolean isCommentLine(String t) {',to:'return t.startsWith(',text:'判断纯注释行前缀。'},{at:'static int countEffectiveEdits(',to:'return _s.size();',text:'骨架有效改动行统计，要你补全 TODO 1。'},{at:'private static String pythonBin() {',to:'return System.getProperty',text:'跨平台选择 Python 命令。'},{at:'public RunResponse run(',to:'throw new StudyService.StudyException',text:'校验与沙箱运行主逻辑，要你补全 TODO 2、3。'},{at:'// controller/PlaygroundController.java',to:'return playground.run(',text:'实验场控制器：先校验登录态再转交业务层。'}],solution:{code:'// service/PlaygroundService.java\npackage com.example.zixishi.service;\n\nimport com.example.zixishi.sandbox.SandboxRunner;\nimport java.io.IOException;\nimport java.nio.charset.StandardCharsets;\nimport java.util.Arrays;\nimport java.util.HashSet;\nimport java.util.List;\nimport java.util.Set;\nimport org.springframework.stereotype.Service;\nimport tools.jackson.core.type.TypeReference;\nimport tools.jackson.databind.ObjectMapper;\n\n@Service\npublic class PlaygroundService {\n\n    public record Problem(String id, String title, String language, String starter) {}\n\n    public record CaseResult(String name, boolean ok, String actual, String expected) {}\n\n    public record RunResponse(int passed, int total, long timeMs, String stdout, String stderr,\n                              boolean timedOut, boolean truncated, List<CaseResult> cases) {}\n\n    private static final Problem TWO_SUM = new Problem(\n        "two-sum",\n        "两数之和",\n        "python",\n        "def two_sum(nums: list[int], target: int) -> list[int]:\\n"\n            + "    # TODO：返回和为 target 的两个元素下标 [i, j]\\n"\n            + "    pass\\n"\n    );\n\n    private static final String TWO_SUM_HARNESS = """\n        import json, sys, traceback\n        _cases = [\n            ("示例 1", [2, 7, 11, 15], 9, [0, 1]),\n            ("示例 2", [3, 2, 4], 6, [1, 2]),\n            ("重复元素", [3, 3], 6, [0, 1]),\n        ]\n        _results = []\n        for _name, _nums, _target, _expected in _cases:\n            try:\n                _actual = two_sum(list(_nums), _target)\n                _results.append({"name": _name, "ok": _actual == _expected, "actual": json.dumps(_actual, ensure_ascii=False), "expected": json.dumps(_expected)})\n            except Exception as _e:\n                traceback.print_exc(file=sys.stderr)\n                _results.append({"name": _name, "ok": False, "actual": f"{type(_e).__name__}: {_e}", "expected": json.dumps(_expected)})\n        with open("_cases.json", "w", encoding="utf-8") as _f:\n            json.dump(_results, _f, ensure_ascii=False)\n        """;\n\n    private final SandboxRunner runner;\n    private final ObjectMapper json;\n\n    public PlaygroundService(SandboxRunner runner, ObjectMapper json) {\n        this.runner = runner;\n        this.json = json;\n    }\n\n    public List<Problem> problems() {\n        return List.of(TWO_SUM);\n    }\n\n    private static boolean isCommentLine(String t) {\n        return t.startsWith("//") || t.startsWith("#") || t.startsWith("--") || t.startsWith("/*") || t.startsWith("*");\n    }\n\n    static int countEffectiveEdits(String userCode, String starterCode) {\n        Set<String> starter = new HashSet<>();\n        for (String line : starterCode.split("\\\\r?\\\\n")) {\n            String t = line.strip();\n            if (!t.isEmpty()) starter.add(t);\n        }\n        int edits = 0;\n        for (String line : userCode.split("\\\\r?\\\\n")) {\n            String t = line.strip();\n            if (t.isEmpty() || isCommentLine(t) || starter.contains(t)) continue;\n            edits++;\n        }\n        return edits;\n    }\n\n    private static String pythonBin() {\n        String env = System.getenv("PYTHON_BIN");\n        if (env != null && !env.isBlank()) return env;\n        return System.getProperty("os.name").toLowerCase().contains("win") ? "python" : "python3";\n    }\n\n    public RunResponse run(String problemId, String language, String code) {\n        if (!TWO_SUM.id().equals(problemId)) {\n            throw new StudyService.StudyException(404, "题目不存在");\n        }\n        if (!"python".equals(language)) {\n            throw new StudyService.StudyException(400, "暂不支持该编程语言");\n        }\n        String raw = code == null ? "" : code;\n        if (raw.isBlank() || raw.getBytes(StandardCharsets.UTF_8).length > 32 * 1024) {\n            throw new StudyService.StudyException(400, "代码不能为空，且不能超过 32 KB");\n        }\n        if (countEffectiveEdits(raw, TWO_SUM.starter()) == 0) {\n            throw new StudyService.StudyException(400, "请先补全 TODO 代码后再运行");\n        }\n        try {\n            SandboxRunner.RunResult res = runner.run(\n                "main.py", raw + "\\n" + TWO_SUM_HARNESS, "_cases.json", List.of(pythonBin(), "main.py"));\n            List<CaseResult> cases = res.resultJson().isEmpty()\n                ? List.of()\n                : json.readValue(res.resultJson(), new TypeReference<List<CaseResult>>() {});\n            int passed = (int) cases.stream().filter(CaseResult::ok).count();\n            return new RunResponse(passed, 3, res.timeMs(), res.stdout(), res.stderr(),\n                res.timedOut(), res.truncated(), cases);\n        } catch (IOException | InterruptedException e) {\n            if (e instanceof InterruptedException) Thread.currentThread().interrupt();\n            throw new StudyService.StudyException(500, "沙箱运行失败");\n        }\n    }\n}\n\n// controller/PlaygroundController.java\npackage com.example.zixishi.controller;\n\nimport com.example.zixishi.service.AuthService;\nimport com.example.zixishi.service.PlaygroundService;\nimport java.util.Map;\nimport org.springframework.web.bind.annotation.*;\n\n@RestController\n@RequestMapping("/api/playground")\npublic class PlaygroundController {\n\n    public record RunBody(String problemId, String language, String code) {}\n\n    private final AuthService auth;\n    private final PlaygroundService playground;\n\n    public PlaygroundController(AuthService auth, PlaygroundService playground) {\n        this.auth = auth;\n        this.playground = playground;\n    }\n\n    @GetMapping("/problems")\n    public Map<String, Object> problems(@CookieValue(name = "session", required = false) String token) {\n        auth.currentUser(token);\n        return Map.of("items", playground.problems());\n    }\n\n    @PostMapping("/run")\n    public PlaygroundService.RunResponse run(@CookieValue(name = "session", required = false) String token,\n                                             @RequestBody RunBody body) {\n        auth.currentUser(token);\n        return playground.run(body.problemId(), body.language(), body.code());\n    }\n}',explain:[{at:'// service/PlaygroundService.java',to:'import tools.jackson.databind.ObjectMapper;',text:'实验场业务逻辑层：注入 SandboxRunner 和 Jackson 3 ObjectMapper。'},{at:'@Service',to:'boolean timedOut, boolean truncated, List<CaseResult> cases) {}',text:'声明题目、单个用例结果与判题响应的数据结构。'},{at:'private static final Problem TWO_SUM',to:'""";',text:'内置“两数之和”题面骨架以及隐藏测试驱动（把结果写入 _cases.json）。'},{at:'private final SandboxRunner runner;',to:'return List.of(TWO_SUM);',text:'构造函数注入与题目列表方法。'},{at:'private static boolean isCommentLine(String t) {',to:'return t.startsWith(',text:'判断纯注释行前缀。'},{at:'static int countEffectiveEdits(',to:'return edits;',text:'先用 Set 收集骨架的非空行，再过滤空行、注释和原骨架行，算出真正新增或改动的代码行数。'},{at:'private static String pythonBin() {',to:'return System.getProperty',text:'跨平台选择 Python 命令。'},{at:'public RunResponse run(',to:'throw new StudyService.StudyException(400, "请先补全 TODO 代码后再运行");',text:'依次检查题目存在、语言支持、代码长度与有效改动，未通过时复用 StudyException 返回 400 或 404。'},{at:'try {',to:'throw new StudyService.StudyException(500, "沙箱运行失败");',text:'注入测试驱动交给沙箱执行，解析 _cases.json 统计通过数并构造结构化返回。'},{at:'// controller/PlaygroundController.java',to:'return playground.run(',text:'实验场控制器：先认人再转发请求。'}]}},node:{practice:{steps:['新建 src/services/playground.js 和 src/routes/playground.js，补完 TODO 1、2、3。','在 app.js 的 /api/playground 下挂载新路由：app.use("/api/playground", require("./src/routes/playground"));（放在 notFound 前面）。','启动服务 node app.js 确认没有语法和启动错误。'],expect:'服务正常监听 8080 端口，未报错'},code:'// src/services/playground.js\nconst { runInSandbox } = require("../sandbox/runner");\n\nclass PlaygroundError extends Error {\n  constructor(status, message) {\n    super(message);\n    this.status = status;\n  }\n}\n\nconst TWO_SUM = {\n  id: "two-sum",\n  title: "两数之和",\n  language: "python",\n  starter: [\n    "def two_sum(nums: list[int], target: int) -> list[int]:",\n    "    # TODO：返回和为 target 的两个元素下标 [i, j]",\n    "    pass",\n    "",\n  ].join("\\n"),\n};\n\nconst TWO_SUM_HARNESS = `\nimport json, sys, traceback\n_cases = [\n    ("示例 1", [2, 7, 11, 15], 9, [0, 1]),\n    ("示例 2", [3, 2, 4], 6, [1, 2]),\n    ("重复元素", [3, 3], 6, [0, 1]),\n]\n_results = []\nfor _name, _nums, _target, _expected in _cases:\n    try:\n        _actual = two_sum(list(_nums), _target)\n        _results.append({"name": _name, "ok": _actual == _expected, "actual": json.dumps(_actual, ensure_ascii=False), "expected": json.dumps(_expected)})\n    except Exception as _e:\n        traceback.print_exc(file=sys.stderr)\n        _results.append({"name": _name, "ok": False, "actual": f"{type(_e).__name__}: {_e}", "expected": json.dumps(_expected)})\nwith open("_cases.json", "w", encoding="utf-8") as _f:\n    json.dump(_results, _f, ensure_ascii=False)\n`;\n\nfunction isCommentLine(t) {\n  return t.startsWith("//") || t.startsWith("#") || t.startsWith("--") || t.startsWith("/*") || t.startsWith("*");\n}\n\nfunction countEffectiveEdits(userCode, starterCode) {\n  // TODO 1：把 starterCode 按 /\\r?\\n/ 拆行并 trim 放进 Set，\n  //         统计 userCode 中非空、非 isCommentLine 且不在 Set 中的有效行数\n  return 0;\n}\n\nfunction pythonBin() {\n  if (process.env.PYTHON_BIN) return process.env.PYTHON_BIN;\n  return process.platform === "win32" ? "python" : "python3";\n}\n\nfunction problems() {\n  return [TWO_SUM];\n}\n\nasync function runCode({ problemId, language, code }) {\n  // TODO 2：校验 problemId 等于 "two-sum"（404）、language 等于 "python"（400）、\n  //         code 是字符串且 trim 非空且 UTF-8 字节 <= 32 * 1024（400）、countEffectiveEdits > 0（400）\n  // TODO 3：调用 runInSandbox("main.py", code + "\\n" + TWO_SUM_HARNESS, "_cases.json", pythonBin(), ["main.py"])；\n  //         解析 resultJson（空时为 []），统计 passed 数量并返回 { passed, total: 3, timeMs, stdout, stderr, timedOut, truncated, cases }\n  return { passed: 0, total: 3, timeMs: 0, stdout: "", stderr: "", timedOut: false, truncated: false, cases: [] };\n}\n\nmodule.exports = { PlaygroundError, problems, runCode };\n\n// src/routes/playground.js\nconst express = require("express");\nconst pg = require("../services/playground");\nconst { requireUser } = require("../middleware");\n\nconst router = express.Router();\n\nrouter.get("/problems", requireUser, (req, res) => {\n  res.json({ items: pg.problems() });\n});\n\nrouter.post("/run", requireUser, async (req, res, next) => {\n  try {\n    res.json(await pg.runCode(req.body || {}));\n  } catch (err) {\n    if (err instanceof pg.PlaygroundError) return res.status(err.status).json({ error: err.message });\n    next(err);\n  }\n});\n\nmodule.exports = router;\n\n// app.js：在 notFound 中间件前面加上\napp.use("/api/playground", require("./src/routes/playground"));',explain:[{at:'// src/services/playground.js',to:'const { runInSandbox } = require("../sandbox/runner");',text:'引入任务一写的沙箱运行器。'},{at:'class PlaygroundError extends Error {',to:'this.status = status;',text:'带状态码的业务错误类。'},{at:'const TWO_SUM = {',to:'].join("\\n"),',text:'内置“两数之和”题面骨架。'},{at:'const TWO_SUM_HARNESS = `',to:'`;',text:'隐藏测试驱动，结果写入 _cases.json，异常写入 stderr。'},{at:'function isCommentLine(t) {',to:'return t.startsWith',text:'识别注释前缀。'},{at:'function countEffectiveEdits(userCode, starterCode) {',to:'return 0;',text:'骨架有效改动统计，要你补全 TODO 1。'},{at:'function pythonBin() {',to:'return process.platform',text:'跨平台选择 Python 命令。'},{at:'function problems() {',to:'return { passed: 0, total: 3,',text:'返回题目列表与判题入口，runCode 要你补全 TODO 2、3。'},{at:'module.exports = { PlaygroundError, problems, runCode };',text:'导出业务函数。'},{at:'// src/routes/playground.js',to:'app.use("/api/playground", require("./src/routes/playground"));',text:'挂上需要登录校验的实验场路由，并处理业务错误状态码。'}],solution:{code:'// src/services/playground.js\nconst { runInSandbox } = require("../sandbox/runner");\n\nclass PlaygroundError extends Error {\n  constructor(status, message) {\n    super(message);\n    this.status = status;\n  }\n}\n\nconst TWO_SUM = {\n  id: "two-sum",\n  title: "两数之和",\n  language: "python",\n  starter: [\n    "def two_sum(nums: list[int], target: int) -> list[int]:",\n    "    # TODO：返回和为 target 的两个元素下标 [i, j]",\n    "    pass",\n    "",\n  ].join("\\n"),\n};\n\nconst TWO_SUM_HARNESS = `\nimport json, sys, traceback\n_cases = [\n    ("示例 1", [2, 7, 11, 15], 9, [0, 1]),\n    ("示例 2", [3, 2, 4], 6, [1, 2]),\n    ("重复元素", [3, 3], 6, [0, 1]),\n]\n_results = []\nfor _name, _nums, _target, _expected in _cases:\n    try:\n        _actual = two_sum(list(_nums), _target)\n        _results.append({"name": _name, "ok": _actual == _expected, "actual": json.dumps(_actual, ensure_ascii=False), "expected": json.dumps(_expected)})\n    except Exception as _e:\n        traceback.print_exc(file=sys.stderr)\n        _results.append({"name": _name, "ok": False, "actual": f"{type(_e).__name__}: {_e}", "expected": json.dumps(_expected)})\nwith open("_cases.json", "w", encoding="utf-8") as _f:\n    json.dump(_results, _f, ensure_ascii=False)\n`;\n\nfunction isCommentLine(t) {\n  return t.startsWith("//") || t.startsWith("#") || t.startsWith("--") || t.startsWith("/*") || t.startsWith("*");\n}\n\nfunction countEffectiveEdits(userCode, starterCode) {\n  const starter = new Set(starterCode.split(/\\r?\\n/).map((l) => l.trim()).filter(Boolean));\n  let edits = 0;\n  for (const raw of userCode.split(/\\r?\\n/)) {\n    const t = raw.trim();\n    if (!t || isCommentLine(t) || starter.has(t)) continue;\n    edits++;\n  }\n  return edits;\n}\n\nfunction pythonBin() {\n  if (process.env.PYTHON_BIN) return process.env.PYTHON_BIN;\n  return process.platform === "win32" ? "python" : "python3";\n}\n\nfunction problems() {\n  return [TWO_SUM];\n}\n\nasync function runCode({ problemId, language, code }) {\n  if (problemId !== TWO_SUM.id) throw new PlaygroundError(404, "题目不存在");\n  if (language !== "python") throw new PlaygroundError(400, "暂不支持该编程语言");\n  const raw = typeof code === "string" ? code : "";\n  if (!raw.trim() || Buffer.byteLength(raw, "utf8") > 32 * 1024) {\n    throw new PlaygroundError(400, "代码不能为空，且不能超过 32 KB");\n  }\n  if (countEffectiveEdits(raw, TWO_SUM.starter) === 0) {\n    throw new PlaygroundError(400, "请先补全 TODO 代码后再运行");\n  }\n  const res = await runInSandbox("main.py", raw + "\\n" + TWO_SUM_HARNESS, "_cases.json", pythonBin(), ["main.py"]);\n  const cases = res.resultJson ? JSON.parse(res.resultJson) : [];\n  const passed = cases.filter((c) => c.ok).length;\n  return {\n    passed,\n    total: 3,\n    timeMs: res.timeMs,\n    stdout: res.stdout,\n    stderr: res.stderr,\n    timedOut: res.timedOut,\n    truncated: res.truncated,\n    cases,\n  };\n}\n\nmodule.exports = { PlaygroundError, problems, runCode };\n\n// src/routes/playground.js\nconst express = require("express");\nconst pg = require("../services/playground");\nconst { requireUser } = require("../middleware");\n\nconst router = express.Router();\n\nrouter.get("/problems", requireUser, (req, res) => {\n  res.json({ items: pg.problems() });\n});\n\nrouter.post("/run", requireUser, async (req, res, next) => {\n  try {\n    res.json(await pg.runCode(req.body || {}));\n  } catch (err) {\n    if (err instanceof pg.PlaygroundError) return res.status(err.status).json({ error: err.message });\n    next(err);\n  }\n});\n\nmodule.exports = router;\n\n// app.js：在 notFound 中间件前面加上\napp.use("/api/playground", require("./src/routes/playground"));',explain:[{at:'// src/services/playground.js',to:'const { runInSandbox } = require("../sandbox/runner");',text:'引入任务一写的沙箱运行器。'},{at:'class PlaygroundError extends Error {',to:'this.status = status;',text:'带状态码的业务错误类。'},{at:'const TWO_SUM = {',to:'].join("\\n"),',text:'内置“两数之和”题面骨架。'},{at:'const TWO_SUM_HARNESS = `',to:'`;',text:'隐藏测试驱动。'},{at:'function isCommentLine(t) {',to:'return t.startsWith',text:'识别注释前缀。'},{at:'function countEffectiveEdits(userCode, starterCode) {',to:'return edits;',text:'用 Set 装下骨架非空行，再逐行过滤空行、注释与骨架已有行，算出有效改动行数。'},{at:'function pythonBin() {',to:'return process.platform',text:'跨平台选择 Python 命令。'},{at:'function problems() {',to:'throw new PlaygroundError(400, "请先补全 TODO 代码后再运行");',text:'依次校验题目、语言、源码大小以及有效改动行。'},{at:'const res = await runInSandbox(',to:'cases,',text:'拼接测试驱动送入沙箱，读取结果文件并统计通过数量。'},{at:'module.exports = { PlaygroundError, problems, runCode };',text:'导出业务函数。'},{at:'// src/routes/playground.js',to:'app.use("/api/playground", require("./src/routes/playground"));',text:'挂上需要登录校验的实验场路由并处理异常状态码。'}]}},python:{practice:{steps:['新建 app/services/playground.py 和 app/routers/playground.py，补完 TODO 1、2、3。','在 main.py 注册 playground 路由并加上 PlaygroundError 的异常处理。','启动服务 python main.py 确认没有报错。'],expect:'Uvicorn 正常启动并监听 8080 端口'},code:'# app/services/playground.py\nimport json\nimport sys\n\nfrom app.sandbox.runner import run_in_sandbox\n\n\nclass PlaygroundError(Exception):\n    def __init__(self, status: int, message: str):\n        super().__init__(message)\n        self.status = status\n        self.message = message\n\n\nTWO_SUM = {\n    "id": "two-sum",\n    "title": "两数之和",\n    "language": "python",\n    "starter": (\n        "def two_sum(nums: list[int], target: int) -> list[int]:\\n"\n        "    # TODO：返回和为 target 的两个元素下标 [i, j]\\n"\n        "    pass\\n"\n    ),\n}\n\nTWO_SUM_HARNESS = """\nimport json, sys, traceback\n_cases = [\n    ("示例 1", [2, 7, 11, 15], 9, [0, 1]),\n    ("示例 2", [3, 2, 4], 6, [1, 2]),\n    ("重复元素", [3, 3], 6, [0, 1]),\n]\n_results = []\nfor _name, _nums, _target, _expected in _cases:\n    try:\n        _actual = two_sum(list(_nums), _target)\n        _results.append({"name": _name, "ok": _actual == _expected, "actual": json.dumps(_actual, ensure_ascii=False), "expected": json.dumps(_expected)})\n    except Exception as _e:\n        traceback.print_exc(file=sys.stderr)\n        _results.append({"name": _name, "ok": False, "actual": f"{type(_e).__name__}: {_e}", "expected": json.dumps(_expected)})\nwith open("_cases.json", "w", encoding="utf-8") as _f:\n    json.dump(_results, _f, ensure_ascii=False)\n"""\n\n\ndef is_comment_line(t: str) -> bool:\n    return t.startswith(("//", "#", "--", "/*", "*"))\n\n\ndef count_effective_edits(user_code: str, starter_code: str) -> int:\n    # TODO 1：把 starter_code 按行拆分并 strip() 放进 set，\n    #         统计 user_code 中非空、非 is_comment_line 且不在 starter 集合里的有效行数\n    return 0\n\n\ndef run_code(problem_id: str, language: str, code: str) -> dict:\n    # TODO 2：校验 problem_id == "two-sum"（404）、language == "python"（400）、\n    #         code 非空且 UTF-8 字节数 <= 32 * 1024（400）、count_effective_edits > 0（400）\n    # TODO 3：调用 run_in_sandbox("main.py", code + "\\n" + TWO_SUM_HARNESS, "_cases.json", [sys.executable, "main.py"])；\n    #         解析 resultJson，统计 passed 数量并返回结果字典（total 为 3）\n    _ = (json, sys, run_in_sandbox)\n    return {}\n\n\n# app/routers/playground.py\nfrom fastapi import APIRouter, Depends\nfrom pydantic import BaseModel\n\nfrom app.routers.study import require_user\nfrom app.services import playground\n\nrouter = APIRouter(prefix="/api/playground")\n\n\nclass RunBody(BaseModel):\n    problemId: str = ""\n    language: str = ""\n    code: str = ""\n\n\n@router.get("/problems")\ndef problems(user=Depends(require_user)):\n    return {"items": [playground.TWO_SUM]}\n\n\n@router.post("/run")\ndef run(body: RunBody, user=Depends(require_user)):\n    return playground.run_code(body.problemId, body.language, body.code)\n\n\n# main.py（在路由注册与异常处理器旁边加上）\nfrom app.routers import playground as playground_routes\nfrom app.services.playground import PlaygroundError\n\napp.include_router(playground_routes.router)\n\n\n@app.exception_handler(PlaygroundError)\nasync def playground_error(request: Request, exc: PlaygroundError):\n    return JSONResponse({"error": exc.message}, status_code=exc.status)',explain:[{at:'# app/services/playground.py',to:'self.message = message',text:'导入沙箱运行器并定义带状态码的业务错误。'},{at:'TWO_SUM = {',to:'"    pass\\n"',text:'内置“两数之和”题面与初始骨架。'},{at:'TWO_SUM_HARNESS = """',to:'json.dump(_results, _f, ensure_ascii=False)',text:'隐藏测试驱动：调用用户实现的 two_sum 并把用例详情写入 _cases.json，遇到异常将调用栈打印到 stderr。'},{at:'"""',to:'return 0',text:'注释判断与骨架 Diff 计数函数，count_effective_edits 要你补全。'},{at:'def run_code(',to:'return {}',text:'校验并调用沙箱执行的核心函数，要你补全。'},{at:'# app/routers/playground.py',to:'return JSONResponse({"error": exc.message}, status_code=exc.status)',text:'注册需要登录的实验场路由，并把 PlaygroundError 转成对应状态码的 JSON 错误。'}],solution:{code:'# app/services/playground.py\nimport json\nimport sys\n\nfrom app.sandbox.runner import run_in_sandbox\n\n\nclass PlaygroundError(Exception):\n    def __init__(self, status: int, message: str):\n        super().__init__(message)\n        self.status = status\n        self.message = message\n\n\nTWO_SUM = {\n    "id": "two-sum",\n    "title": "两数之和",\n    "language": "python",\n    "starter": (\n        "def two_sum(nums: list[int], target: int) -> list[int]:\\n"\n        "    # TODO：返回和为 target 的两个元素下标 [i, j]\\n"\n        "    pass\\n"\n    ),\n}\n\nTWO_SUM_HARNESS = """\nimport json, sys, traceback\n_cases = [\n    ("示例 1", [2, 7, 11, 15], 9, [0, 1]),\n    ("示例 2", [3, 2, 4], 6, [1, 2]),\n    ("重复元素", [3, 3], 6, [0, 1]),\n]\n_results = []\nfor _name, _nums, _target, _expected in _cases:\n    try:\n        _actual = two_sum(list(_nums), _target)\n        _results.append({"name": _name, "ok": _actual == _expected, "actual": json.dumps(_actual, ensure_ascii=False), "expected": json.dumps(_expected)})\n    except Exception as _e:\n        traceback.print_exc(file=sys.stderr)\n        _results.append({"name": _name, "ok": False, "actual": f"{type(_e).__name__}: {_e}", "expected": json.dumps(_expected)})\nwith open("_cases.json", "w", encoding="utf-8") as _f:\n    json.dump(_results, _f, ensure_ascii=False)\n"""\n\n\ndef is_comment_line(t: str) -> bool:\n    return t.startswith(("//", "#", "--", "/*", "*"))\n\n\ndef count_effective_edits(user_code: str, starter_code: str) -> int:\n    starter = {line.strip() for line in starter_code.splitlines() if line.strip()}\n    edits = 0\n    for raw in user_code.splitlines():\n        t = raw.strip()\n        if not t or is_comment_line(t) or t in starter:\n            continue\n        edits += 1\n    return edits\n\n\ndef run_code(problem_id: str, language: str, code: str) -> dict:\n    if problem_id != TWO_SUM["id"]:\n        raise PlaygroundError(404, "题目不存在")\n    if language != "python":\n        raise PlaygroundError(400, "暂不支持该编程语言")\n    raw = code if isinstance(code, str) else ""\n    if not raw.strip() or len(raw.encode("utf-8")) > 32 * 1024:\n        raise PlaygroundError(400, "代码不能为空，且不能超过 32 KB")\n    if count_effective_edits(raw, TWO_SUM["starter"]) == 0:\n        raise PlaygroundError(400, "请先补全 TODO 代码后再运行")\n    res = run_in_sandbox("main.py", raw + "\\n" + TWO_SUM_HARNESS, "_cases.json", [sys.executable, "main.py"])\n    cases = json.loads(res["resultJson"]) if res["resultJson"] else []\n    passed = sum(1 for c in cases if c.get("ok"))\n    return {\n        "passed": passed,\n        "total": 3,\n        "timeMs": res["timeMs"],\n        "stdout": res["stdout"],\n        "stderr": res["stderr"],\n        "timedOut": res["timedOut"],\n        "truncated": res["truncated"],\n        "cases": cases,\n    }\n\n\n# app/routers/playground.py\nfrom fastapi import APIRouter, Depends\nfrom pydantic import BaseModel\n\nfrom app.routers.study import require_user\nfrom app.services import playground\n\nrouter = APIRouter(prefix="/api/playground")\n\n\nclass RunBody(BaseModel):\n    problemId: str = ""\n    language: str = ""\n    code: str = ""\n\n\n@router.get("/problems")\ndef problems(user=Depends(require_user)):\n    return {"items": [playground.TWO_SUM]}\n\n\n@router.post("/run")\ndef run(body: RunBody, user=Depends(require_user)):\n    return playground.run_code(body.problemId, body.language, body.code)\n\n\n# main.py（在路由注册与异常处理器旁边加上）\nfrom app.routers import playground as playground_routes\nfrom app.services.playground import PlaygroundError\n\napp.include_router(playground_routes.router)\n\n\n@app.exception_handler(PlaygroundError)\nasync def playground_error(request: Request, exc: PlaygroundError):\n    return JSONResponse({"error": exc.message}, status_code=exc.status)',explain:[{at:'# app/services/playground.py',to:'self.message = message',text:'导入沙箱运行器并定义带状态码的业务错误。'},{at:'TWO_SUM = {',to:'"    pass\\n"',text:'内置“两数之和”题面与初始骨架。'},{at:'TWO_SUM_HARNESS = """',to:'json.dump(_results, _f, ensure_ascii=False)',text:'隐藏测试驱动：把每个用例结果写入 _cases.json。'},{at:'"""',to:'return edits',text:'把骨架行放入集合，再过滤空行、注释行与原骨架行，算出有效修改行数。'},{at:'def run_code(',to:'raise PlaygroundError(400, "请先补全 TODO 代码后再运行")',text:'依次检查题目存在、语言支持、源码大小与有效改动行，拦截无效或未编辑的提交。'},{at:'res = run_in_sandbox(',to:'"cases": cases,',text:'用当前解释器 sys.executable 在沙箱里执行拼接后的代码，读回 _cases.json 汇总通过数并返回。'},{at:'# app/routers/playground.py',to:'return JSONResponse({"error": exc.message}, status_code=exc.status)',text:'注册需要登录的实验场路由，并把 PlaygroundError 转成对应状态码的 JSON 错误。'}]}}}},
  {title:'任务三：前端实验场编辑器：骨架加载、运行与重置',body:'在页面上提供在线编程实验场：打开页面从 /api/playground/problems 拉取题目和代码骨架，点击“运行”提交到 /api/playground/run 并用 textContent 安全展示耗时、stdout/stderr 和每条测试用例的通过情况，点击“重置”恢复成初始骨架。如果你选了后端模板渲染，也可以直接参照原生 HTML + JS 版挂载一个静态页面。',variants:{html:{body:'新建实验场页面 playground.html 和交互脚本 playground.js：加载骨架、发请求跑判题、逐条渲染测试用例对错，并支持重置回初始骨架。',practice:{steps:['在后端静态目录新建 playground.html 和 playground.js，补完 TODO 1、2、3。','在页面导航栏加一个指向 playground.html 的链接。','登录后打开 playground.html，先直接点“运行”看提示“请先补全 TODO 代码”，再补全代码运行通过全部用例，最后点“重置”确认恢复骨架。'],expect:'3 / 3 通过 · 42 ms\n✓ 示例 1：[0, 1]\n✓ 示例 2：[1, 2]\n✓ 重复元素：[0, 1]'},code:'<!-- playground.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>代码实验场 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>代码实验场</h1>\n  <p>\n    <label for="problemSelect">题目</label>\n    <select id="problemSelect"></select>\n    <button id="runBtn" type="button">运行</button>\n    <button id="resetBtn" type="button">重置</button>\n  </p>\n  <textarea id="codeEditor" rows="12" cols="72" placeholder="补全代码"></textarea>\n  <p id="status"></p>\n  <ul id="caseList"></ul>\n  <pre id="outputBox"></pre>\n  <script src="playground.js"></script>\n</body>\n</html>\n\n// playground.js\nconst selectEl = document.getElementById("problemSelect");\nconst editorEl = document.getElementById("codeEditor");\nconst runBtn = document.getElementById("runBtn");\nconst resetBtn = document.getElementById("resetBtn");\nconst statusEl = document.getElementById("status");\nconst caseListEl = document.getElementById("caseList");\nconst outputEl = document.getElementById("outputBox");\n\nlet problems = [];\nlet current = null;\n\nasync function loadProblems() {\n  // TODO 1：GET /api/playground/problems（若 401 跳转 login.html）；\n  //         保存 items 到 problems，填充 selectEl 的 option，把第一题设为 current 并写入 editorEl.value\n}\n\nfunction renderResult(data) {\n  // TODO 2：在 statusEl 显示“通过数 / 总数 · 耗时 ms”（超时时加上超时标记）；\n  //         用 textContent 遍历 data.cases 渲染 ✓/✗ 到 caseListEl，在 outputEl 显示 stdout 与 stderr\n}\n\nrunBtn.addEventListener("click", async () => {\n  if (!current) return;\n  runBtn.disabled = true;\n  statusEl.textContent = "运行中…";\n  caseListEl.replaceChildren();\n  outputEl.textContent = "";\n  try {\n    // TODO 3：POST /api/playground/run（传 problemId、language、code）；\n    //         响应非 2xx 时抛出 error 字段，成功则调用 renderResult(data)\n  } catch (err) {\n    statusEl.textContent = err.message;\n  } finally {\n    runBtn.disabled = false;\n  }\n});\n\nresetBtn.addEventListener("click", () => {\n  if (!current) return;\n  editorEl.value = current.starter;\n  statusEl.textContent = "";\n  caseListEl.replaceChildren();\n  outputEl.textContent = "";\n});\n\nloadProblems().catch((err) => { statusEl.textContent = err.message; });',explain:[{at:'<!-- playground.html -->',to:'</html>',text:'精简的实验场页面：题目选择、运行与重置按钮、代码编辑框、状态栏、用例列表和输出区。'},{at:'// playground.js',to:'let current = null;',text:'获取页面元素并维护题目列表和当前选中题。'},{at:'async function loadProblems() {',text:'加载题库与初始骨架，要你补全 TODO 1。',to:'function renderResult(data) {'},{at:'// TODO 2',text:'渲染结构化判题结果，要你补全 TODO 2。',to:'runBtn.addEventListener("click", async () => {'},{at:'if (!current) return;',to:'} catch (err) {',text:'点击运行后先禁用按钮防止连点，清空上次输出后发请求；TODO 3 处补全请求与校验。'},{at:'statusEl.textContent = err.message;',to:'});',text:'请求出错时显示后端返回的原因，最后恢复按钮可点击状态。'},{at:'resetBtn.addEventListener("click", () => {',to:'loadProblems().catch((err) => { statusEl.textContent = err.message; });',text:'点击重置直接把输入框恢复为 current.starter 初始骨架，并清掉上次运行输出。'}],solution:{code:'<!-- playground.html -->\n<!DOCTYPE html>\n<html lang="zh-CN">\n<head>\n  <meta charset="utf-8">\n  <title>代码实验场 - 面试自习室</title>\n</head>\n<body>\n  <p><a href="/">← 返回题库</a></p>\n  <h1>代码实验场</h1>\n  <p>\n    <label for="problemSelect">题目</label>\n    <select id="problemSelect"></select>\n    <button id="runBtn" type="button">运行</button>\n    <button id="resetBtn" type="button">重置</button>\n  </p>\n  <textarea id="codeEditor" rows="12" cols="72" placeholder="补全代码"></textarea>\n  <p id="status"></p>\n  <ul id="caseList"></ul>\n  <pre id="outputBox"></pre>\n  <script src="playground.js"></script>\n</body>\n</html>\n\n// playground.js\nconst selectEl = document.getElementById("problemSelect");\nconst editorEl = document.getElementById("codeEditor");\nconst runBtn = document.getElementById("runBtn");\nconst resetBtn = document.getElementById("resetBtn");\nconst statusEl = document.getElementById("status");\nconst caseListEl = document.getElementById("caseList");\nconst outputEl = document.getElementById("outputBox");\n\nlet problems = [];\nlet current = null;\n\nasync function loadProblems() {\n  const res = await fetch("/api/playground/problems");\n  if (res.status === 401) {\n    location.href = "login.html";\n    return;\n  }\n  const data = await res.json();\n  problems = data.items || [];\n  selectEl.replaceChildren(...problems.map((p) => {\n    const opt = document.createElement("option");\n    opt.value = p.id;\n    opt.textContent = p.title;\n    return opt;\n  }));\n  current = problems[0] || null;\n  if (current) editorEl.value = current.starter;\n}\n\nselectEl.addEventListener("change", () => {\n  current = problems.find((p) => p.id === selectEl.value) || null;\n  if (current) editorEl.value = current.starter;\n});\n\nfunction renderResult(data) {\n  const flags = [data.timedOut ? "超时" : "", data.truncated ? "输出已截断" : ""].filter(Boolean).join(" · ");\n  statusEl.textContent = `${data.passed} / ${data.total} 通过 · ${data.timeMs} ms${flags ? " · " + flags : ""}`;\n  caseListEl.replaceChildren(...(data.cases || []).map((c) => {\n    const li = document.createElement("li");\n    li.textContent = `${c.ok ? "✓" : "✗"} ${c.name}：实际 ${c.actual}，期望 ${c.expected}`;\n    return li;\n  }));\n  outputEl.textContent = [data.stdout && "stdout:\\n" + data.stdout, data.stderr && "stderr:\\n" + data.stderr]\n    .filter(Boolean).join("\\n");\n}\n\nrunBtn.addEventListener("click", async () => {\n  if (!current) return;\n  runBtn.disabled = true;\n  statusEl.textContent = "运行中…";\n  caseListEl.replaceChildren();\n  outputEl.textContent = "";\n  try {\n    const res = await fetch("/api/playground/run", {\n      method: "POST",\n      headers: { "Content-Type": "application/json" },\n      body: JSON.stringify({ problemId: current.id, language: current.language, code: editorEl.value }),\n    });\n    const data = await res.json();\n    if (!res.ok) throw new Error(data.error || "运行失败");\n    renderResult(data);\n  } catch (err) {\n    statusEl.textContent = err.message;\n  } finally {\n    runBtn.disabled = false;\n  }\n});\n\nresetBtn.addEventListener("click", () => {\n  if (!current) return;\n  editorEl.value = current.starter;\n  statusEl.textContent = "";\n  caseListEl.replaceChildren();\n  outputEl.textContent = "";\n});\n\nloadProblems().catch((err) => { statusEl.textContent = err.message; });',explain:[{at:'<!-- playground.html -->',to:'</html>',text:'精简的实验场页面结构。'},{at:'// playground.js',to:'let current = null;',text:'获取页面元素并记录题目状态。'},{at:'async function loadProblems() {',to:'if (current) editorEl.value = current.starter;',text:'加载题目并在未登录时跳登录页，随后填入下拉框并把首题的代码骨架放进编辑器。'},{at:'selectEl.addEventListener("change", () => {',to:'if (current) editorEl.value = current.starter;',text:'切换题目时更新 current 并加载新题目骨架。'},{at:'function renderResult(data) {',to:'.filter(Boolean).join("\\n");',text:'用 textContent 安全渲染通过数、耗时、超时/截断标记、逐条用例结果和输出流，防 XSS。'},{at:'runBtn.addEventListener("click", async () => {',to:'loadProblems().catch((err) => { statusEl.textContent = err.message; });',text:'发请求到 /api/playground/run，支持禁用防连点、错误提示与一键重置骨架。'}]}},react:{body:'新增 PlaygroundPage 组件（/?page=playground）：加载题目与代码骨架、维护编辑内容与运行中状态、请求 /api/playground/run 并结构化显示用例结果，支持点击“重置”恢复初始骨架。',practice:{steps:['新建 src/PlaygroundPage.jsx，补完 TODO 1、2、3。','在 src/App.jsx 加上路由分支（if (params.get("page") === "playground") return <PlaygroundPage />;），并在导航栏加上入口链接。','登录后打开 /?page=playground，验证骨架加载、运行报错提示、通过全部用例与重置功能。'],expect:'3 / 3 通过 · 42 ms\n✓ 示例 1：[0, 1]\n✓ 示例 2：[1, 2]\n✓ 重复元素：[0, 1]'},code:'// src/PlaygroundPage.jsx\nimport { useEffect, useState } from "react";\n\nexport default function PlaygroundPage() {\n  const [problems, setProblems] = useState([]);\n  const [currentId, setCurrentId] = useState("");\n  const [code, setCode] = useState("");\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState("");\n  const [result, setResult] = useState(null);\n\n  const current = problems.find((p) => p.id === currentId) || null;\n\n  useEffect(() => {\n    // TODO 1：GET /api/playground/problems（401 跳转 /?page=login）；\n    //         把 items 放进 problems，若非空则设置 currentId 和 code 为第一题骨架\n  }, []);\n\n  function selectProblem(id) {\n    const next = problems.find((p) => p.id === id) || null;\n    setCurrentId(id);\n    setCode(next ? next.starter : "");\n    setResult(null);\n    setError("");\n  }\n\n  async function handleRun() {\n    if (!current || busy) return;\n    setBusy(true);\n    setError("");\n    setResult(null);\n    try {\n      // TODO 2：POST /api/playground/run，请求体为 { problemId: current.id, language: current.language, code }；\n      //         非 2xx 时 setError(data.error)，否则 setResult(data)\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  function handleReset() {\n    // TODO 3：把 code 恢复为 current.starter，清空 result 和 error\n  }\n\n  return (\n    <main>\n      <p><a href="/">← 返回题库</a></p>\n      <h1>代码实验场</h1>\n      <p>\n        <select value={currentId} onChange={(e) => selectProblem(e.target.value)} aria-label="题目">\n          {problems.map((p) => <option key={p.id} value={p.id}>{p.title}</option>)}\n        </select>{" "}\n        <button type="button" onClick={handleRun} disabled={busy}>{busy ? "运行中…" : "运行"}</button>{" "}\n        <button type="button" onClick={handleReset} disabled={!current || busy}>重置</button>\n      </p>\n      <textarea rows={12} cols={72} placeholder="补全代码" value={code} onChange={(e) => setCode(e.target.value)} />\n      {error && <p>{error}</p>}\n      {result && (\n        <section>\n          <p>{result.passed} / {result.total} 通过 · {result.timeMs} ms{result.timedOut ? " · 超时" : ""}{result.truncated ? " · 输出已截断" : ""}</p>\n          <ul>\n            {(result.cases || []).map((c, i) => (\n              <li key={i}>{c.ok ? "✓" : "✗"} {c.name}：实际 {c.actual}，期望 {c.expected}</li>\n            ))}\n          </ul>\n          {(result.stdout || result.stderr) && (\n            <pre>{[result.stdout && "stdout:\\n" + result.stdout, result.stderr && "stderr:\\n" + result.stderr].filter(Boolean).join("\\n")}</pre>\n          )}\n        </section>\n      )}\n    </main>\n  );\n}',explain:[{at:'// src/PlaygroundPage.jsx',to:'const current = problems.find((p) => p.id === currentId) || null;',text:'声明题目列表、当前题目编号、编辑器代码、运行锁、错误与结果六个状态。'},{at:'useEffect(() => {',to:'}, []);',text:'页面挂载时拉取题目列表并填充默认骨架，要你补全 TODO 1。'},{at:'function selectProblem(id) {',to:'setError("");',text:'切换题目时加载对应骨架并清理上一次判题结果。'},{at:'async function handleRun() {',to:'function handleReset() {',text:'运行与重置逻辑，要你补全 TODO 2、3。'},{at:'return (',to:'</main>',text:'精简界面：下拉选题、运行与重置按钮、受控文本框，以及结构化结果与输出渲染。'}],solution:{code:'// src/PlaygroundPage.jsx\nimport { useEffect, useState } from "react";\n\nexport default function PlaygroundPage() {\n  const [problems, setProblems] = useState([]);\n  const [currentId, setCurrentId] = useState("");\n  const [code, setCode] = useState("");\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState("");\n  const [result, setResult] = useState(null);\n\n  const current = problems.find((p) => p.id === currentId) || null;\n\n  useEffect(() => {\n    let ignore = false;\n    async function load() {\n      const res = await fetch("/api/playground/problems");\n      if (res.status === 401) {\n        window.location.href = "/?page=login";\n        return;\n      }\n      const data = await res.json();\n      const items = data.items || [];\n      if (ignore || !items.length) return;\n      setProblems(items);\n      setCurrentId(items[0].id);\n      setCode(items[0].starter);\n    }\n    load().catch((err) => setError(err.message));\n    return () => { ignore = true; };\n  }, []);\n\n  function selectProblem(id) {\n    const next = problems.find((p) => p.id === id) || null;\n    setCurrentId(id);\n    setCode(next ? next.starter : "");\n    setResult(null);\n    setError("");\n  }\n\n  async function handleRun() {\n    if (!current || busy) return;\n    setBusy(true);\n    setError("");\n    setResult(null);\n    try {\n      const res = await fetch("/api/playground/run", {\n        method: "POST",\n        headers: { "Content-Type": "application/json" },\n        body: JSON.stringify({ problemId: current.id, language: current.language, code }),\n      });\n      const data = await res.json();\n      if (!res.ok) throw new Error(data.error || "运行失败");\n      setResult(data);\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  function handleReset() {\n    if (!current) return;\n    setCode(current.starter);\n    setResult(null);\n    setError("");\n  }\n\n  return (\n    <main>\n      <p><a href="/">← 返回题库</a></p>\n      <h1>代码实验场</h1>\n      <p>\n        <select value={currentId} onChange={(e) => selectProblem(e.target.value)} aria-label="题目">\n          {problems.map((p) => <option key={p.id} value={p.id}>{p.title}</option>)}\n        </select>{" "}\n        <button type="button" onClick={handleRun} disabled={busy}>{busy ? "运行中…" : "运行"}</button>{" "}\n        <button type="button" onClick={handleReset} disabled={!current || busy}>重置</button>\n      </p>\n      <textarea rows={12} cols={72} placeholder="补全代码" value={code} onChange={(e) => setCode(e.target.value)} />\n      {error && <p>{error}</p>}\n      {result && (\n        <section>\n          <p>{result.passed} / {result.total} 通过 · {result.timeMs} ms{result.timedOut ? " · 超时" : ""}{result.truncated ? " · 输出已截断" : ""}</p>\n          <ul>\n            {(result.cases || []).map((c, i) => (\n              <li key={i}>{c.ok ? "✓" : "✗"} {c.name}：实际 {c.actual}，期望 {c.expected}</li>\n            ))}\n          </ul>\n          {(result.stdout || result.stderr) && (\n            <pre>{[result.stdout && "stdout:\\n" + result.stdout, result.stderr && "stderr:\\n" + result.stderr].filter(Boolean).join("\\n")}</pre>\n          )}\n        </section>\n      )}\n    </main>\n  );\n}',explain:[{at:'// src/PlaygroundPage.jsx',to:'const current = problems.find((p) => p.id === currentId) || null;',text:'声明组件状态。'},{at:'useEffect(() => {',to:'}, []);',text:'挂载时获取题目并填上默认骨架；用 ignore 防止组件卸载后继续 setState。'},{at:'function selectProblem(id) {',to:'setError("");',text:'切换题目并重置编辑器内容和旧结果。'},{at:'async function handleRun() {',to:'setBusy(false);',text:'向 /api/playground/run 发送请求并更新结果状态。'},{at:'function handleReset() {',to:'setError("");',text:'恢复当前题目的初始骨架并清空之前的运行提示。'},{at:'return (',to:'</main>',text:'精简 JSX 渲染，自动对文本转义防 XSS。'}]}}}},
  {title:'验收：检查正常判题、报错捕获、死循环超时与输出截断',body:'用下面的验收脚本一次性验证第 18 关全部核心防线：未登录拦截、未改动 TODO 骨架拦截、正常实现全部通过、逻辑错误返回用例对比、运行时异常捕获到 stderr、死循环在超时时间附近及时熔断，以及海量打印被安全截断且不影响结构化判题结果。',practice:{steps:['保持后端服务在 8080 端口运行。','将脚本保存为 checks/check_l18.py，运行 python checks/check_l18.py（Mac 用 python3）。','全部通过后提交代码：git add . 然后 git commit -m "第 18 关：在线编程实验场与代码沙箱"。'],expect:'✓ 没登录时不能运行实验场代码\n✓ 原样提交骨架或只加注释返回 400\n✓ 正确实现通过全部 3 个测试用例\n✓ 逻辑错误返回用例失败详情\n✓ 运行时报错被捕获到 stderr\n✓ 死循环在限定时间内超时熔断\n✓ 海量打印输出被截断且不影响判题\n\n通过 7 / 7'},code:'import http.cookiejar\nimport json\nimport random\nimport sys\nimport time\nimport urllib.error\nimport urllib.request\n\nBASE = sys.argv[1] if len(sys.argv) > 1 else "http://localhost:8080"\npassed = 0\n\n\ndef check(name, ok):\n    global passed\n    print(("✓ " if ok else "✗ ") + name)\n    passed += bool(ok)\n\n\ndef new_client():\n    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(http.cookiejar.CookieJar()))\n\n    def call(method, path, body=None):\n        data = json.dumps(body).encode("utf-8") if body is not None else None\n        req = urllib.request.Request(BASE + path, data=data, method=method, headers={"Content-Type": "application/json"})\n        try:\n            with opener.open(req, timeout=15) as r:\n                status, raw = r.status, r.read()\n        except urllib.error.HTTPError as e:\n            status, raw = e.code, e.read()\n        except OSError as e:\n            sys.exit(f"连不上 {BASE}，服务启动了吗？（{e}）")\n        try:\n            return status, json.loads(raw.decode("utf-8") or "null")\n        except ValueError:\n            return status, None\n\n    return call\n\n\ndef obj(value):\n    return value if isinstance(value, dict) else {}\n\n\ndef run_py(client, code):\n    return client("POST", "/api/playground/run", {"problemId": "two-sum", "language": "python", "code": code})\n\n\nanon, me = new_client(), new_client()\nuser = {"username": f"pg_{random.randint(100000, 999999)}", "password": "secret123"}\nme("POST", "/api/register", user)\nme("POST", "/api/login", user)\n\nstatus, _ = run_py(anon, "def two_sum(nums, target): return [0, 1]")\ncheck("没登录时不能运行实验场代码", status == 401)\n\n_, pdata = me("GET", "/api/playground/problems")\nstarter = (obj(pdata).get("items") or [{}])[0].get("starter", "")\ns1, _ = run_py(me, starter)\ns2, _ = run_py(me, starter + "\\n# 只是加一行注释\\n")\ncheck("原样提交骨架或只加注释返回 400", bool(starter) and s1 == 400 and s2 == 400)\n\ngood_code = """\ndef two_sum(nums, target):\n    seen = {}\n    for i, x in enumerate(nums):\n        if target - x in seen:\n            return [seen[target - x], i]\n        seen[x] = i\n    return []\n"""\nst, r = run_py(me, good_code)\nd = obj(r)\ncheck(\n    "正确实现通过全部 3 个测试用例",\n    st == 200 and d.get("passed") == 3 and d.get("total") == 3 and len(d.get("cases") or []) == 3 and d.get("timeMs", -1) >= 0,\n)\n\nst, r = run_py(me, "def two_sum(nums, target):\\n    return [0, 0]")\nd = obj(r)\ncases = d.get("cases") or []\ncheck("逻辑错误返回用例失败详情", st == 200 and d.get("passed") == 0 and d.get("total") == 3 and any(not c.get("ok") for c in cases))\n\nst, r = run_py(me, "def two_sum(nums, target):\\n    return 1 / 0")\nd = obj(r)\ncheck("运行时报错被捕获到 stderr", st == 200 and d.get("passed") == 0 and "ZeroDivisionError" in str(d.get("stderr", "")))\n\nt0 = time.monotonic()\nst, r = run_py(me, "def two_sum(nums, target):\\n    while True:\\n        pass")\nelapsed = time.monotonic() - t0\nd = obj(r)\ncheck(\n    "死循环在限定时间内超时熔断",\n    st == 200 and elapsed < 5.0 and d.get("passed") == 0 and (d.get("timedOut") is True or "超时" in str(d.get("stderr", ""))),\n)\n\nloud_code = good_code + "\\nprint(\'A\' * 100000)\\n"\nst, r = run_py(me, loud_code)\nd = obj(r)\nout = str(d.get("stdout", ""))\ncheck(\n    "海量打印输出被截断且不影响判题",\n    st == 200 and d.get("passed") == 3 and len(out.encode("utf-8")) <= 20000 and (d.get("truncated") is True or "截断" in out),\n)\n\nprint(f"\\n通过 {passed} / 7")',explain:[{at:'import http.cookiejar',to:'import urllib.request',text:'只用 Python 标准库发请求与统计耗时。'},{at:'BASE = sys.argv[1]',to:'passed += bool(ok)',text:'服务地址、检查计数与打印辅助函数。'},{at:'def new_client():',to:'return call',text:'带独立 Cookie 罐的客户端，把状态码和解析后的 JSON 打包返回。'},{at:'def obj(value):',to:'return client("POST", "/api/playground/run"',text:'字典兜底和快捷调用 /api/playground/run 的辅助函数。'},{at:'anon, me = new_client(), new_client()',to:'check("没登录时不能运行实验场代码", status == 401)',text:'注册并登录测试用户，同时先确认未登录访问被 401 拦截。'},{at:'_, pdata = me("GET", "/api/playground/problems")',to:'check("原样提交骨架或只加注释返回 400"',text:'拉取内置题目骨架，分别原样提交和仅加注释提交，验证 starter-diff 拦截生效（400）。'},{at:'good_code = """',to:'d.get("timeMs", -1) >= 0,',text:'提交正确的 two_sum 实现，验证 3 个隐藏用例全部通过且返回了耗时与用例列表。'},{at:'st, r = run_py(me, "def two_sum(nums, target):\\n    return [0, 0]")',to:'check("逻辑错误返回用例失败详情"',text:'提交固定错误返回值，验证 passed=0 且 cases 里包含失败用例的详细对比。'},{at:'st, r = run_py(me, "def two_sum(nums, target):\\n    return 1 / 0")',to:'check("运行时报错被捕获到 stderr"',text:'验证运行抛异常不会让后端崩掉，而是把 ZeroDivisionError 栈捕获到 stderr。'},{at:'t0 = time.monotonic()',to:'d.get("timedOut") is True',text:'提交死循环，验证总耗时不超过 5 秒就被沙箱强杀熔断并返回超时状态。'},{at:'loud_code = good_code + "\\nprint(\'A\' * 100000)\\n"',to:'print(f"\\n通过 {passed} / 7")',text:'打印 10 万个 A，验证 stdout 体积被截断在安全范围内，且由于判题结果走独立 _cases.json，依然能准确拿到 passed=3。'}]},
  {title:'这一关学到了什么',body:'一、浏览器沙箱（Web Worker / WASM）零服务器算力、可随时 terminate()，适合前端即时试跑；但原生编译语言和权威判题必须在服务端受控执行；\n二、服务端绝对不能直接 eval/exec 用户代码，也不能把输入拼进未净化的 shell（sh -c），要用参数数组在独立临时目录里拉起子进程并过滤环境变量；\n三、四道防线缺一不可：进程组超时强杀、内存与源码大小上限、流式截断输出并排空管道、defer / finally 清理临时目录；\n四、借助骨架 Diff（过滤空行、注释行与原骨架行），能在启动沙箱前就拦截“没写有效代码”的白交；\n五、隐藏测试驱动注入后，将结构化用例结果写进独立文件，与 stdout/stderr 分离，就算用户代码狂打日志触发截断，判题结果依然完整可靠。\n\n下一关预告（第 19 关：JD 深度调研、参考简历与专项补题）：基于目标岗位 JD 提炼考察维度、对照参考简历定位短板，并生成针对性的专项补题计划。'}
 ],quiz:[
  {id:'pj-playground-1',q:'为什么不能在后端服务进程里直接用 eval() 或 exec() 执行用户提交的代码？',options:['eval 执行速度慢，会让所有接口延迟翻倍','代码与主服务同进程，可能读取密钥或删库','eval 语法不支持多行函数定义和循环语句','浏览器不允许接口返回 eval 计算后的结果'],why:['问题不在执行速度，而在权限与进程隔离边界完全丧失。','','多数动态语言的 eval/exec 都支持多行语句，真正风险是安全隔离。','浏览器只接收后端返回的 JSON，并不关心后端内部如何执行。'],answer:1,explain:'直接在后端主进程里 eval/exec，用户代码就能访问当前进程的环境变量（如 AI_API_KEY）、文件系统（如 SQLite 数据库）甚至直接终止整个服务进程。'},
  {id:'pj-playground-2',q:'启动子进程运行用户代码时，为什么要用参数数组直接启动，而避免拼接 sh -c "..."？',options:['参数数组启动可以跳过代码语法编译检查步骤','sh -c 无法将子进程的标准输出重定向到管道','避免输入里的分号、反引号等字符触发命令注入','参数数组模式会自动把子进程内存限制为 256MB'],why:['编译器或解释器依然会做语法检查，参数数组只是跳过 shell 解析。','sh -c 同样可以通过管道重定向标准输出。','','内存上限需要通过 setrlimit、ulimit 或容器参数额外配置。'],answer:2,explain:'经由 shell 解析字符串时，特殊字符（如 ;、&&、$()、反引号）会被当作新命令执行引发命令注入；直接传参数数组（shell=False）会把代码路径原样交给目标解释器或编译器。'},
  {id:'pj-playground-3',q:'在判断“用户是否真的写了代码”的骨架 Diff 检查中，哪些行应当被忽略不计入有效改动？',options:['所有包含数字字面量或数组下标的行','函数体内缩进超过四个空格的逻辑行','函数名里带有下划线或驼峰命名的行','空行、纯注释行以及原样来自骨架的行'],why:['数字与下标往往正是算法核心逻辑，不能忽略。','缩进深的是正常业务逻辑代码，应当计入有效改动。','函数命名风格不影响是否修改了 TODO 实现。',''],answer:3,explain:'空行、纯注释行和原样保留的骨架模板行都没有实现逻辑，只有剔除它们之后还有新增或修改的行，才说明用户真正写了代码。'},
  {id:'pj-playground-4',type:'multi',q:'设计服务端受控代码沙箱时，下面哪些防护措施是合理的？（多选）',options:['超时期满后强制终止整个子进程组','截断超出上限的 stdout 与 stderr 输出','把 AI_API_KEY 等环境变量完整传给子进程','每次运行建独立临时目录并在结束时清理'],why:['','','传给子进程的环境变量必须做白名单精简，绝不能暴露后端密钥。',''],answers:[0,1,3],explain:'超时强杀进程组、截断输出防止内存撑爆、隔离并清理临时目录都是沙箱核心防线；环境变量则要做最小白名单过滤，不能携带密钥。'},
  {id:'pj-playground-5',type:'multi',q:'关于浏览器 Web Worker 沙箱与服务端隔离沙箱的区别，下面说法正确的有？（多选）',options:['Web Worker 无法直接访问 DOM，超时可强杀线程','Web Worker 可以原生直接编译运行 Go 和 Java 源码','权威判题与隐藏测试用例宜放在服务端沙箱执行','只要用了 Web Worker，前端传回的分数就可直接入库'],why:['','浏览器本身不带 Go 或 JDK 工具链，原生编译型语言仍需服务端或专用环境。','','客户端传回的任何结果都可被篡改，正式判题分数必须由服务端算出。'],answers:[0,2],explain:'Web Worker 适合在浏览器安全试跑 JS/TS 且可随时 terminate()，但涉及隐藏测试用例和权威成绩判定时，依然要放在受控的服务端沙箱执行。'},
  {id:'pj-playground-6',type:'judge',q:'为了防止用户打印死循环撑爆内存，后端只要停止从子进程 stdout 管道读取数据就够了，不需要截断后继续排空管道。',answer:false,explain:'错误。操作系统的管道缓冲区容量有限（通常几十 KB），如果后端停读而不排空也不中止进程，子进程写满缓冲区就会阻塞挂起，一直拖到超时为止；因此超过上限后需要一边丢弃多余字节（或直接中止），一边记录 truncated 标记。'},
  {id:'pj-playground-7',type:'fill',q:'在浏览器端执行 JS/TS 代码时，常把它放到隔离的 ＿＿ 线程里，既不阻塞界面渲染，超时也能直接调用 terminate() 中止。',accepted:['Web Worker','web worker'],explain:'Web Worker。它运行在独立的后台线程，无法访问 window 和 document，把 fetch 等网络 API 置空后即可安全试跑前端代码，超时可直接 terminate()。'},
  {id:'pj-playground-8',type:'short',q:'如果把隐藏测试用例的判题结果 JSON 直接打印到 stdout 最后一行，当用户代码在循环里疯狂 print 大量文本触发输出截断时，会出现什么问题？应该如何避免？',reference:'问题：stdout 超过上限被截断后，末尾打印的测试结果 JSON 会被截掉或残缺，导致后端无法解析用例通过情况，误判或报解析错误；同时用户自己打印若碰巧包含相同前缀也可能干扰解析。改进：把结构化用例结果写入临时目录里约定的独立结果文件（或专用文件描述符），stdout/stderr 只负责收集用户的程序打印并在上限处安全截断，两者互不干扰。',points:['指出 stdout 截断会破坏末尾的结果 JSON（或导致误解析）','说明用户自身打印内容也可能干扰纯文本标记','提出将结构化结果写入独立文件或专用管道/描述符，与 stdout/stderr 隔离'],explain:'把“给人看的输出流”和“给程序解析的判题结果”拆开，是沙箱判题器最稳妥的设计之一。'},
  {id:'pj-playground-code-1',type:'code',q:'实现辅助函数 countEffectiveEdits(userCode, starterCode)：统计用户代码相对于初始骨架的有效改动行数。规则：按换行（支持 \\r\\n 和 \\n）拆行并去掉首尾空白；忽略空行，忽略以 //、# 或 -- 开头的纯注释行，忽略在初始代码骨架中也原样出现过的行；返回剩余有效改动行的数量。',reference:'function countEffectiveEdits(userCode: string, starterCode: string): number {\n  const isComment = (t: string) =>\n    t.startsWith(\'//\') || t.startsWith(\'#\') || t.startsWith(\'--\');\n  const starterLines = new Set(\n    starterCode.split(/\\r?\\n/).map((l) => l.trim()).filter(Boolean),\n  );\n  let count = 0;\n  for (const raw of userCode.split(/\\r?\\n/)) {\n    const t = raw.trim();\n    if (!t || isComment(t) || starterLines.has(t)) continue;\n    count++;\n  }\n  return count;\n}',points:['按 \\r?\\n 拆行并对每行执行首尾空白清理（trim/strip），忽略空行','识别并跳过以 //、#、-- 开头的纯注释行','将 starterCode 中的非空行构建成集合（Set/map），用于 O(1) 比对原骨架行','仅统计既非空行、非注释行、又不在原骨架集合中的有效修改行数量'],explain:'这一步对应项目里 lib/starter-diff.ts 的核心思路：剔除框架模板自带的签名、空行与注释后，才能准确判断学习者是否真的动手写了代码。'},
  {id:'pj-playground-go-1',stack:'go',q:'Go 用 exec.CommandContext 启动沙箱子进程时，设置 cmd.WaitDelay 的主要作用是？',options:['让子进程在启动前额外等待一段时间再执行','把超时后的退出码自动映射成 HTTP 400 状态码','避免孙进程占用管道导致父进程久等阻塞','限制子进程在运行时最多可申请的堆内存大小'],why:['WaitDelay 是在超时取消后起作用，不会推迟启动。','WaitDelay 只影响管道关闭与 Wait 返回，不负责 HTTP 状态码。','','内存限制需要通过 rlimit 或容器配置，和 WaitDelay 无关。'],answer:2,explain:'当主进程被超时杀掉但派生出的孙进程还继承并占用着 stdout/stderr 管道时，cmd.Wait() 会一直等管道关闭而卡死；设置 WaitDelay 后超期就会强制关闭管道并返回。'},
  {id:'pj-playground-java-1',stack:'java',q:'Java 的 ProcessBuilder 启动沙箱子进程超时后，为什么还要遍历 process.descendants() 强杀？',options:['防止子进程派生的孙进程继续在后台占用 CPU','Java 规定必须先清掉子进程才能调用 destroy','为了把标准错误流里还没读完的数据刷新出来','让 JVM 自动回收临时目录里刚创建的源码文件'],why:['','destroyForcibly() 可直接调用，遍历 descendants 是为了避免留下孤儿孙进程。','读取输出流需要单独读取线程，强杀孙进程不会自动刷新流数据。','临时目录仍需在 finally 代码块中显式递归删除。'],answer:0,explain:'只杀掉直接子进程时，它可能已经派生出孙进程留在后台继续消耗 CPU 和内存；遍历 descendants() 一并 destroyForcibly() 才能把整棵进程树清理干净。'},
  {id:'pj-playground-node-1',stack:'node',q:'Node.js 里用 spawn 启动沙箱子进程相比 exec() 的优势主要是什么？',options:['spawn 会自动把所有代码放进 Web Worker 运行','spawn 不经由 shell 解析参数，可防注入且流式读取','spawn 在进程异常退出时不会触发任何回调事件','exec() 不支持设置 cwd 工作目录和 env 环境变量'],why:['Web Worker 是浏览器 API，Node.js 的 spawn 启动的是操作系统子进程。','','spawn 正常会触发 exit/close 事件，方便收集退出码。','exec() 同样支持 cwd 与 env，但默认经由 shell 执行且会整段缓冲输出。'],answer:1,explain:'exec() 默认先启动 shell 再把整段输出缓存进内存；spawn() 直接按参数数组启动进程不走 shell，还可以通过流式事件在达到字节上限时立刻截断，安全性和内存控制都更好。'},
  {id:'pj-playground-python-1',stack:'python',q:'Python 在 POSIX 系统用 subprocess.Popen 启动沙箱时，配合 start_new_session=True 和 os.killpg 的目的是？',options:['让子进程直接继承父进程的全部环境变量和密钥','允许子进程在独立会话里绕过虚拟内存大小限制','让脚本在后台脱离控制继续运行，不受超时影响','让子进程自成新进程组，超时时能整组一起强杀'],why:['环境变量是否继承由 env 参数控制，与 start_new_session 无关。','限制内存需要用 resource.setrlimit，新会话不会绕过限制。','沙箱正好相反，必须受超时控制而非长期后台驻留。',''],answer:3,explain:'start_new_session=True 让子进程成为新进程组的组长，超时后调用 os.killpg(proc.pid, signal.SIGKILL) 就能向整个进程组发信号，把子进程及其派生的孙进程一次全部强杀。'}
 ]};
